/// 编辑焦点在格内还是编辑栏。缓冲只有一个（`self.editing`），位置只决定谁拿焦点。
#[derive(Default, Clone, Copy, PartialEq, Eq, Debug)]
enum EditSpot {
    /// 格内编辑框（键入 / F2 / 双击进入）
    #[default]
    Grid,
    /// 编辑栏输入行（点编辑栏或 fx 进入）
    FormulaBar,
}

#[derive(Default, Clone)]
struct EditState {
    buf: String,
    spot: EditSpot,
    /// 自动补全当前高亮项；缓冲区/候选变化时会被夹到范围内。
    complete_idx: usize,
    /// 最近一次处理 Alt+Enter 的帧，防止同一帧重复插入换行
    alt_frame: u64,
    /// 光标位置（字符下标）：点选单元格建立引用时按它插入/替换
    caret: usize,
    /// 下一步要把 TextEdit 的光标强制搬到这个字符位置（补全/点选引用后）
    caret_override: Option<usize>,
    /// 仅在进入编辑 / 切换编辑栏 / 选引用回焦时主动夺回键盘焦点，避免每帧抢走侧栏 AI 输入框焦点
    focus_requested: bool,
    /// 编辑子模式（输入 / 编辑 / 点选引用）
    mode: EditMode,
    /// 记忆式键入的候选后缀（在光标处虚显，按 Enter/Tab 接受，按 Backspace 放弃）
    autocomplete_suffix: Option<String>,
    /// 记忆式键入匹配的完整原文（保留列中原有大小写，接受补全时整串替换）
    autocomplete_full: Option<String>,
    /// 当前是否处于输入法组合态（收到非空 Preedit 置 true，Commit/空 Preedit/Disabled 清 false），
    /// 防止中文 IME 按 ↑↓ 选候选词的中间帧误触发方向键提交拼音。
    ime_composing: bool,
    /// 缓存公式/文本排版 `Galley` `(buf, font_size_bits, wrap_w_bits, Arc<Galley>)`，避免光标闪烁帧重复解析着色。
    cached_galley: std::cell::RefCell<Option<(String, u32, u32, std::sync::Arc<egui::Galley>)>>,
    /// 缓存格内浮层宽度测量 `(buf, font_size_bits, max_line_w)`。
    cached_max_line_w: std::cell::RefCell<Option<(String, u32, f32)>>,
    /// 缓存本表公式多引用彩色高亮框 `(buf, sheet_idx, Arc<Vec<((u32, u32, u32, u32), usize)>>)`。
    cached_local_refs: std::cell::RefCell<
        Option<(
            String,
            usize,
            std::sync::Arc<Vec<((u32, u32, u32, u32), usize)>>,
        )>,
    >,
}

impl EditState {
    fn new(buf: String) -> Self {
        let caret = buf.chars().count();
        Self {
            buf,
            spot: EditSpot::Grid,
            complete_idx: 0,
            alt_frame: u64::MAX,
            caret,
            caret_override: None,
            focus_requested: true,
            mode: EditMode::Edit,
            autocomplete_suffix: None,
            autocomplete_full: None,
            ime_composing: false,
            cached_galley: std::cell::RefCell::new(None),
            cached_max_line_w: std::cell::RefCell::new(None),
            cached_local_refs: std::cell::RefCell::new(None),
        }
    }

    fn layout_formula_cached(
        &self,
        ui: &egui::Ui,
        text: &str,
        font: egui::FontId,
        wrap_width: f32,
    ) -> std::sync::Arc<egui::Galley> {
        let f_bits = font.size.to_bits();
        let w_bits = wrap_width.to_bits();
        if let Some((ref c_txt, cf, cw, ref g)) = *self.cached_galley.borrow() {
            if cf == f_bits && cw == w_bits && c_txt == text {
                return g.clone();
            }
        }
        let mut job = formula_layout_job(text, font, theme::palette().default_cell_text);
        job.wrap.max_width = wrap_width;
        let g = ui.fonts(|f| f.layout_job(job));
        *self.cached_galley.borrow_mut() = Some((text.to_owned(), f_bits, w_bits, g.clone()));
        g
    }
}

/// UI-11.4：公式提交时记账「最近使用的函数」。
/// 测试默认不写真实用户目录；要验这条线路的用例用 `TestEnv` 隔离 LOCALAPPDATA
/// 并显式打开 `SC_FNRECENT_RECORD`。
pub(crate) fn note_formula_use(text: &str) {
    if cfg!(test) && !debug_flags::fnrecent_record() {
        return;
    }
    fnrecent::record_formula(text);
}

