/// 拖选或拖填充柄越出内容视口边缘时计算自动滚动速度（px/帧）。
fn edge_autoscroll(pos: egui::Pos2, content: Rect, dt: f32) -> Vec2 {
    let dt = dt.clamp(0.004, 0.05);
    let axis = |v: f32, lo: f32, hi: f32| -> f32 {
        let over = if v < lo {
            v - lo
        } else if v > hi {
            v - hi
        } else {
            0.0
        };
        if over.abs() < 1.0 {
            return 0.0;
        }
        let speed = (over.abs() * 14.0 + 180.0).min(2400.0);
        over.signum() * speed * dt
    };
    Vec2::new(
        axis(pos.x, content.left(), content.right()),
        axis(pos.y, content.top(), content.bottom()),
    )
}

/// 去掉页眉页脚里的 OOXML 控制码（&L/&C/&R/&B 等），只留文字
/// 列头上的分级 +/- 按钮：在本组最后一列的列头底部画一个 9px 小方块，
/// 点一下收起/展开这一组列（明细列进 hidden_cols）。
#[allow(clippy::too_many_arguments)]
fn col_outline_button(
    ui: &mut egui::Ui,
    painter: &egui::Painter,
    groups: &[(u32, u32, u8)],
    c: u32,
    x: f32,
    w: f32,
    origin_y: f32,
    hh: f32,
    depth: f32,
    wb: &sheetcore::model::Workbook,
    si: usize,
    pending: &mut Vec<(u32, u32)>,
) {
    let (sum_right, symbols_on) = {
        let sh = wb.sheet(si);
        (sh.outline_summary_right, sh.outline_symbols)
    };
    if !symbols_on {
        return;
    }
    for (gs, ge, glv) in groups.iter() {
        let target_col = if sum_right { *ge + 1 } else { gs.saturating_sub(1) };
        if target_col != c {
            continue;
        }
        let sheet = wb.sheet(si);
        let hidden = (*gs..=*ge).all(|x| sheet.hidden_cols.contains(&x));
        let bw = 9.0;
        let bx = x + w / 2.0 - bw / 2.0;
        let by = origin_y + hh - 10.0 - (*glv as f32 - 1.0) * 11.0;
        let _ = depth;
        let brect =
            egui::Rect::from_min_size(egui::pos2(bx, by), Vec2::new(bw, bw));
        let br = ui.interact(
            brect,
            egui::Id::new(("col_outline_btn", *gs, *ge)),
            egui::Sense::click(),
        );
        painter.rect_filled(brect, 1.0, Color32::WHITE);
        painter.rect_stroke(
            brect,
            1.0,
            Stroke::new(1.0, Color32::from_rgb(120, 120, 120)),
            egui::StrokeKind::Inside,
        );
        let ctr = brect.center();
        painter.line_segment(
            [
                egui::pos2(ctr.x - 2.5, ctr.y),
                egui::pos2(ctr.x + 2.5, ctr.y),
            ],
            Stroke::new(1.2, Color32::from_rgb(60, 60, 60)),
        );
        if hidden {
            painter.line_segment(
                [
                    egui::pos2(ctr.x, ctr.y - 2.5),
                    egui::pos2(ctr.x, ctr.y + 2.5),
                ],
                Stroke::new(1.2, Color32::from_rgb(60, 60, 60)),
            );
        }
        if br.clicked() {
            pending.push((*gs, *ge));
        }
    }
}

/// 矩形中心到目标点的连线与矩形的交点（公式审核箭头用）
fn edge_point(x0: f32, y0: f32, x1: f32, y1: f32, tx: f32, ty: f32) -> (f32, f32) {
    let cx = (x0 + x1) * 0.5;
    let cy = (y0 + y1) * 0.5;
    let dx = tx - cx;
    let dy = ty - cy;
    if dx.abs() < 1e-6 && dy.abs() < 1e-6 {
        return (cx, cy);
    }
    let hw = (x1 - x0).abs() * 0.5;
    let hh = (y1 - y0).abs() * 0.5;
    let sx = if dx.abs() > 1e-6 { hw / dx.abs() } else { f32::INFINITY };
    let sy = if dy.abs() > 1e-6 { hh / dy.abs() } else { f32::INFINITY };
    let k = sx.min(sy).min(1.0);
    (cx + dx * k, cy + dy * k)
}

/// 把 "A1"/"$B$2" 解析成 0 基 (行, 列)
fn parse_a1_ref(s: &str) -> Option<(u32, u32)> {
    let t: String = s.chars().filter(|c| *c != '$').collect();
    let mut col = 0u32;
    let mut i = 0usize;
    let bytes = t.as_bytes();
    while i < bytes.len() && bytes[i].is_ascii_alphabetic() {
        col = col * 26 + (bytes[i].to_ascii_uppercase() - b'A' + 1) as u32;
        i += 1;
    }
    if i == 0 || i == bytes.len() {
        return None;
    }
    let row = t[i..].parse::<u32>().ok()?;
    if row == 0 || col == 0 {
        return None;
    }
    Some((row - 1, col - 1))
}

fn chart_handle_at(r: egui::Rect, p: egui::Pos2) -> Option<u8> {
    let pts = [
        (r.left_top(), 1u8),
        (egui::pos2(r.center().x, r.top()), 2),
        (r.right_top(), 3),
        (egui::pos2(r.right(), r.center().y), 4),
        (r.right_bottom(), 5),
        (egui::pos2(r.center().x, r.bottom()), 6),
        (r.left_bottom(), 7),
        (egui::pos2(r.left(), r.center().y), 8),
    ];
    for (pt, m) in pts {
        if (p - pt).length() <= 7.0 {
            return Some(m);
        }
    }
    None
}

