/// 最近文件列表的内存缓存项：避免主页与后台页每帧重复读盘和 stat 网络盘路径。
#[derive(Clone)]
struct HomeRecentEntry {
    path: PathBuf,
    lower_haystack: String,
    name: String,
    short_dir: String,
    size_txt: String,
    mtime_txt: String,
    pinned: bool,
}

/// UI-16：每张工作表自己的视图状态，按 Sheet.identity 绑定。
/// 不能按索引存：重排、改名、删除后索引会变；identity 在运行期稳定。
#[derive(Clone)]
struct SheetViewState {
    sel: (u32, u32),
    sel_end: (u32, u32),
    extra_sel: Vec<(u32, u32, u32, u32)>,
    scroll: Vec2,
    zoom: f32,
    /// UI-16.1：普通/页面布局/分页预览是每张表各自的视图状态
    view_mode: u8,
    split_panes: Option<(u32, u32)>,
    split_scroll: Vec2,
}

impl Default for SheetViewState {
    fn default() -> Self {
        Self {
            sel: (0, 0),
            sel_end: (0, 0),
            extra_sel: Vec::new(),
            scroll: Vec2::ZERO,
            zoom: 1.0,
            view_mode: 0,
            split_panes: None,
            split_scroll: Vec2::ZERO,
        }
    }
}

/// UI-16：移动或复制工作表对话框的草稿（支持当前工作簿、其他已打开标签或新建工作簿）。
#[derive(Clone, Copy)]
struct SheetMoveDlg {
    src: usize,
    copy: bool,
    /// 插入位置：0..=len，len 表示末尾
    target: usize,
    /// 目标工作簿：None = 当前工作簿，Some(usize::MAX) = 新工作簿，Some(tab_idx) = 已打开的其他标签页
    target_doc: Option<usize>,
}

/// 标签页槽位：一个是当前活动的，其余挂起
struct XlinkWatchResult {
    doc_uid: u64,
    resolved: std::collections::HashMap<usize, Option<PathBuf>>,
    updates: Vec<(
        usize,
        (PathBuf, u64, u128),
        (
            Vec<String>,
            std::collections::BTreeMap<(usize, u32, u32), sheetcore::model::Value>,
            Vec<(String, Option<usize>, String)>,
        ),
    )>,
}

enum TabSlot {
    Active,
    Parked(Box<ParkedDoc>),
}

enum OpenMsg {
    /// 文件已读入（带的是上次保存的计算结果，先显示；末项为完整磁盘文件的 SHA-256 指纹）
    Loaded(Box<Workbook>, bool, Box<sheetcore::xlsx::LoadDiag>, String),
    /// 全量重算完成
    Recalced(Box<Workbook>, Box<sheetcore::formula::deps::Deps>),
    /// 大文件只把依赖图备好，不阻塞打开（缓存值先显示）
    DepsReady(Box<sheetcore::formula::deps::Deps>),
    /// 手动“重算全部”的后台结果（带上发起时的 wb_epoch 与 doc_gen）
    RecalcedWb(Box<Workbook>, Box<sheetcore::formula::deps::Deps>, u64, u64, bool),
    /// 后台重算被取消（未写回，模型保持原值）
    RecalcCancelled,
    /// 密码弹窗触发的异步解密失败（回弹密码框并展示错误提示，不阻塞 UI 也不解密两遍）
    PasswordFailed(PathBuf, String),
    Failed(String),
}

