    /// QAT 撤销 / 重做历史列表弹出窗
    fn draw_undo_history_popup(&mut self, ctx: &egui::Context) {
        let Some((is_undo, pos)) = self.undo_history_popup else {
            return;
        };
        let labels = if is_undo {
            self.undo.undo_labels(30)
        } else {
            self.undo.redo_labels(30)
        };
        if labels.is_empty() {
            self.undo_history_popup = None;
            return;
        }
        let mut pick: Option<usize> = None;
        let mut hover_idx: Option<usize> = None;
        let area = egui::Area::new(egui::Id::new("qat_undo_history"))
            .order(egui::Order::Foreground)
            .fixed_pos(pos)
            .show(ctx, |ui| {
                egui::Frame::popup(ui.style()).show(ui, |ui| {
                    ui.set_width(210.0);
                    let pal = theme::palette();
                    let cur_hover: Option<usize> =
                        ui.data(|d| d.get_temp(egui::Id::new("undo_hist_hover")));
                    egui::ScrollArea::vertical().max_height(260.0).show(ui, |ui| {
                        for (idx, lbl) in labels.iter().enumerate() {
                            let (r, resp) = ui.allocate_exact_size(
                                Vec2::new(ui.available_width(), 22.0),
                                Sense::click(),
                            );
                            if resp.hovered() {
                                hover_idx = Some(idx);
                            }
                            let highlighted = cur_hover.is_some_and(|h| idx <= h);
                            if highlighted {
                                ui.painter().rect_filled(r, 3.0, pal.accent_tint);
                            }
                            ui.painter().text(
                                egui::pos2(r.left() + 8.0, r.center().y),
                                Align2::LEFT_CENTER,
                                lbl,
                                FontId::proportional(11.5),
                                pal.text,
                            );
                            if resp.clicked() {
                                pick = Some(idx + 1);
                            }
                        }
                    });
                    ui.data_mut(|d| d.insert_temp(egui::Id::new("undo_hist_hover"), hover_idx));
                    ui.separator();
                    let n = hover_idx.map(|h| h + 1).unwrap_or(1);
                    let verb = if is_undo { "撤销" } else { "重做" };
                    ui.label(
                        egui::RichText::new(format!("{verb} {n} 项操作"))
                            .size(11.0)
                            .color(ui_kit::TEXT_WEAK),
                    );
                });
            });
        if let Some(steps) = pick {
            self.undo_history_popup = None;
            self.apply_undo_steps(!is_undo, steps);
        } else if ctx.input(|i| i.key_pressed(Key::Escape))
            || (ctx.input(|i| i.pointer.any_click())
                && ctx
                    .input(|i| i.pointer.interact_pos())
                    .is_some_and(|p| !area.response.rect.contains(p)))
        {
            self.undo_history_popup = None;
        }
    }

    /// 插入 / 删除单元格移动方向选择对话框（Ctrl+Shift+= / Ctrl+- / 右键单元格…）
    fn shift_cells_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut dlg) = self.shift_cells_dlg.clone() else {
            return;
        };
        let mut open = true;
        let mut apply = false;
        let title = if dlg.insert { "插入" } else { "删除" };
        let labels = if dlg.insert {
            ["活动单元格右移", "活动单元格下移", "整行", "整列"]
        } else {
            ["活动单元格左移", "活动单元格上移", "整行", "整列"]
        };
        ui_kit::window(ctx, title, 260.0).open(&mut open).show(ctx, |ui| {
            ui.add_space(4.0);
            for (idx, lbl) in labels.iter().enumerate() {
                ui.radio_value(&mut dlg.choice, idx as u8, *lbl);
            }
            ui.add_space(6.0);
            if ui.input(|i| i.key_pressed(Key::Enter)) {
                apply = true;
            }
            ui_kit::footer(ui, |ui| {
                if ui_kit::primary_button(ui, "确定").clicked() {
                    apply = true;
                }
                if ui_kit::secondary_button(ui, "取消").clicked() {
                    open = false;
                }
            });
        });
        if apply {
            self.shift_cells_dlg = None;
            let (r1, c1, r2, c2) = self.sel_rect();
            match (dlg.insert, dlg.choice) {
                (true, 0) => self.shift_cells(true, true),
                (true, 1) => self.shift_cells(true, false),
                (true, 2) => self.structural(sheetcore::structural::Structural::InsertRows {
                    at: r1,
                    n: r2 - r1 + 1,
                }),
                (true, _) => self.structural(sheetcore::structural::Structural::InsertCols {
                    at: c1,
                    n: c2 - c1 + 1,
                }),
                (false, 0) => self.shift_cells(false, true),
                (false, 1) => self.shift_cells(false, false),
                (false, 2) => self.delete_rows_range(r1, r2),
                (false, _) => self.structural(sheetcore::structural::Structural::DeleteCols {
                    at: c1,
                    n: c2 - c1 + 1,
                }),
            }
        } else if !open {
            self.shift_cells_dlg = None;
        } else {
            self.shift_cells_dlg = Some(dlg);
        }
    }

    /// 打开「公式求值」分步求值对话框
    pub(crate) fn open_evaluate_formula(&mut self) {
        self.commit_edit(None);
        let (r, c) = self.sel;
        {
            let sh = self.wb.sheet(self.sheet_idx);
            if sh.protection.is_some() && self.wb.styles.get(sh.style_of(r, c)).hidden {
                self.status = "该单元格已设置为隐藏公式，工作表受保护时无法求值".into();
                return;
            }
        }
        let Some(f) = self
            .wb
            .sheet(self.sheet_idx)
            .get(r, c)
            .and_then(|cell| cell.formula.clone())
        else {
            self.status = "当前单元格不含公式，无法公式求值".into();
            return;
        };
        let evaluator = sheetcore::formula::eval_steps::FormulaEvaluator::new(
            &self.wb,
            self.sheet_idx,
            r,
            c,
            &f,
        );
        self.eval_formula_dlg = Some(EvalFormulaDlg {
            sheet_idx: self.sheet_idx,
            row: r,
            col: c,
            evaluator,
            finished_value: None,
        });
    }

    fn eval_formula_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut dlg) = self.eval_formula_dlg.take() else {
            return;
        };
        let mut open = true;
        let step = dlg.evaluator.current(&self.wb);
        let (cur_si, cur_r, cur_c) = dlg.evaluator.active_cell();
        let sheet_name = self
            .wb
            .sheets
            .get(cur_si)
            .map(|s| s.name.as_str())
            .unwrap_or("Sheet1");
        let ref_label = format!("{sheet_name}!{}", cell_name(cur_r, cur_c));
        let depth = dlg.evaluator.depth();
        let mut do_step = false;
        let mut do_step_in = false;
        let mut do_step_out = false;
        let mut do_restart = false;

        ui_kit::window(ctx, "公式求值", 480.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    ui.label(
                        egui::RichText::new(format!("引用：{ref_label}"))
                            .size(12.0)
                            .strong(),
                    );
                    if depth > 1 {
                        ui.label(
                            egui::RichText::new(format!("（步入深度 {depth}）"))
                                .size(11.0)
                                .color(ui_kit::ACCENT),
                        );
                    }
                });
                ui.add_space(6.0);
                ui.label(
                    egui::RichText::new("求值（带下划线部分将在下一步计算）：")
                        .size(11.5)
                        .color(ui_kit::TEXT_WEAK),
                );
                egui::Frame::group(ui.style())
                    .fill(theme::palette().card_bg)
                    .inner_margin(egui::Margin::same(10))
                    .show(ui, |ui| {
                        ui.set_min_width(ui.available_width());
                        ui.set_min_height(48.0);
                        let mut job = egui::text::LayoutJob::default();
                        let font = FontId::monospace(13.5);
                        let pal = theme::palette();
                        let normal = egui::TextFormat {
                            font_id: font.clone(),
                            color: pal.text,
                            ..Default::default()
                        };
                        let under = egui::TextFormat {
                            font_id: font,
                            color: pal.accent,
                            underline: Stroke::new(1.5, pal.accent),
                            ..Default::default()
                        };
                        if let Some((s, e)) = step.highlight
                            && s <= e
                            && e <= step.expr.len()
                            && step.expr.is_char_boundary(s)
                            && step.expr.is_char_boundary(e)
                        {
                            job.append(&step.expr[..s], 0.0, normal.clone());
                            job.append(&step.expr[s..e], 0.0, under);
                            job.append(&step.expr[e..], 0.0, normal);
                        } else {
                            job.append(&step.expr, 0.0, normal);
                        }
                        ui.label(job);
                    });
                ui.add_space(8.0);
                ui_kit::footer(ui, |ui| {
                    if step.done {
                        if ui_kit::primary_button(ui, "重新开始").clicked() {
                            do_restart = true;
                        }
                    } else if ui_kit::primary_button(ui, "求值").clicked() {
                        do_step = true;
                    }
                    if ui
                        .add_enabled(step.step_in_target.is_some(), egui::Button::new("步入"))
                        .clicked()
                    {
                        do_step_in = true;
                    }
                    if ui
                        .add_enabled(depth > 1, egui::Button::new("步出"))
                        .clicked()
                    {
                        do_step_out = true;
                    }
                    if !step.done && ui.button("重新开始").clicked() {
                        do_restart = true;
                    }
                    if ui_kit::secondary_button(ui, "关闭").clicked() {
                        open = false;
                    }
                });
            });
        if do_step {
            dlg.evaluator.step(&self.wb);
            let next = dlg.evaluator.current(&self.wb);
            if next.done {
                dlg.finished_value = Some(next.expr);
            }
        } else if do_step_in {
            dlg.evaluator.step_in(&self.wb);
        } else if do_step_out {
            dlg.evaluator.step_out(&self.wb);
        } else if do_restart {
            dlg.evaluator.restart(&self.wb);
            dlg.finished_value = None;
        }
        if open {
            self.eval_formula_dlg = Some(dlg);
        }
    }

    /// 跨表追踪定位弹窗：列出跨工作表引用/从属目标，点击直接切换工作表并选中
    fn draw_cross_trace_popup(&mut self, ctx: &egui::Context) {
        let Some((origin_rc, targets)) = self.cross_trace_popup.clone() else {
            return;
        };
        let mut open = true;
        let mut jump: Option<(usize, u32, u32, u32, u32)> = None;
        ui_kit::window(ctx, "定位跨表追踪", 360.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(
                    egui::RichText::new(format!(
                        "单元格 {} 的跨表关联引用（点击跳转）：",
                        cell_name(origin_rc.0, origin_rc.1)
                    ))
                    .size(11.5)
                    .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(4.0);
                egui::ScrollArea::vertical().max_height(220.0).show(ui, |ui| {
                    for &(si, r1, c1, r2, c2) in &targets {
                        let sname = self
                            .wb
                            .sheets
                            .get(si)
                            .map(|s| s.name.as_str())
                            .unwrap_or("Sheet");
                        let addr = if r1 == r2 && c1 == c2 {
                            format!("{sname}!{}", cell_name(r1, c1))
                        } else {
                            format!("{sname}!{}:{}", cell_name(r1, c1), cell_name(r2, c2))
                        };
                        if ui_kit::popup_item(ui, &addr, true, 330.0).clicked() {
                            jump = Some((si, r1, c1, r2, c2));
                        }
                    }
                });
                ui_kit::footer(ui, |ui| {
                    if ui_kit::secondary_button(ui, "关闭").clicked() {
                        open = false;
                    }
                });
            });
        if let Some((si, r1, c1, r2, c2)) = jump {
            self.goto_history.push((self.sheet_idx, self.sel.0, self.sel.1));
            if self.goto_history.len() > 64 {
                self.goto_history.remove(0);
            }
            if si < self.wb.sheets.len() && si != self.sheet_idx {
                self.switch_sheet_view(si);
            }
            self.extra_sel.clear();
            self.sel = (r1, c1);
            self.sel_end = (r2, c2);
            self.ensure_visible();
            self.cross_trace_popup = None;
        } else if !open {
            self.cross_trace_popup = None;
        }
    }

    /// 错误检查选项：背景检查开关、标记颜色、两条规则的开关（Excel「错误检查选项」那一页）
    fn ec_options_window(&mut self, ctx: &egui::Context) {
        if !self.ec_options {
            return;
        }
        let mut open = true;
        let mut changed = false;
        let mut reset_all = false;
        ui_kit::window(ctx, "错误检查选项", 470.0)
            .open(&mut open)
            .show(ctx, |ui| {
                if ui
                    .checkbox(&mut self.ec.background, "启用背景错误检查（在单元格左上角标出来）")
                    .changed()
                {
                    changed = true;
                }
                ui.horizontal(|ui| {
                    ui.add_sized([80.0, 20.0], egui::Label::new("标记颜色:"));
                    for (name, rgb) in [
                        ("绿", [40u8, 160, 40]),
                        ("红", [200, 40, 40]),
                        ("蓝", [40, 80, 200]),
                        ("橙", [210, 120, 20]),
                    ] {
                        let on = self.ec.color == rgb;
                        if ui.selectable_label(on, name).clicked() {
                            self.ec.color = rgb;
                            changed = true;
                        }
                        let (r, _) = ui.allocate_exact_size(egui::vec2(14.0, 14.0), egui::Sense::hover());
                        ui.painter().rect_filled(
                            r,
                            2.0,
                            Color32::from_rgb(rgb[0], rgb[1], rgb[2]),
                        );
                    }
                });
                ui.add_space(6.0);
                ui.separator();
                ui.add_space(2.0);
                ui.label(egui::RichText::new("检查规则").font(ui_kit::bold(ui_kit::T_BODY)));
                if ui
                    .checkbox(&mut self.ec.check_errors, "公式错误（#DIV/0!、#N/A、#NAME? 等）")
                    .changed()
                {
                    changed = true;
                }
                if ui
                    .checkbox(&mut self.ec.check_text, "数字以文本形式存储")
                    .changed()
                {
                    changed = true;
                }
                ui.add_space(6.0);
                if ui.button("重置所有忽略的错误").clicked() {
                    reset_all = true;
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        self.ec_options = false;
                    }
                });
            });
        if reset_all {
            {
                let sh = self.wb.sheet_mut(self.sheet_idx);
                sh.ignored_errors.clear();
                sh.ignored_errors_dirty = true;
            }
            self.wb.dirty = true;
            changed = true;
            self.status = "已重置本表忽略的错误".into();
        }
        if changed {
            self.ec.save();
            self.diagnostics.reset_marks();
            if self.error_dlg {
                self.error_list = self.scan_issues();
            }
        }
        if !open {
            self.ec_options = false;
        }
    }

    /// 方案管理器：保存/显示/删除/摘要
    fn scenario_window(&mut self, ctx: &egui::Context) {
        if !self.scen_dlg {
            return;
        }
        let mut open = true;
        let mut do_add = false;
        let mut do_show = false;
        let mut do_del = false;
        let mut do_summary = false;
        let list = &self.wb.sheet(self.sheet_idx).scenarios;
        let mut sel = self.scen_sel;
        ui_kit::window(ctx, "方案管理器", 580.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(
                    egui::RichText::new("这张表里保存的方案（点一条可以装载到下面的名称/备注）")
                        .size(11.5)
                        .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(3.0);
                egui::ScrollArea::vertical().max_height(150.0).show(ui, |ui| {
                    if list.is_empty() {
                        ui.label(egui::RichText::new("还没有方案").size(11.5));
                    }
                    for (i, sc) in list.iter().enumerate() {
                        let mut label = format!("{}（{} 个单元格）", sc.name, sc.cells.len());
                        if !sc.comment.is_empty() {
                            label.push_str(&format!(" — {}", sc.comment));
                        }
                        if ui.selectable_label(sel == Some(i), label).clicked() {
                            sel = Some(i);
                            self.scen_name = sc.name.clone();
                            self.scen_comment = sc.comment.clone();
                        }
                    }
                });
                ui.add_space(4.0);
                ui.separator();
                ui.horizontal(|ui| {
                    ui.add_sized([76.0, 20.0], egui::Label::new("名称:"));
                    ui.add(egui::TextEdit::singleline(&mut self.scen_name).desired_width(240.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([76.0, 20.0], egui::Label::new("备注:"));
                    ui.add(egui::TextEdit::singleline(&mut self.scen_comment).desired_width(240.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([76.0, 20.0], egui::Label::new("可变单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.scen_range).desired_width(120.0));
                    ui.label(
                        egui::RichText::new("例如 A1:C3")
                            .size(11.0)
                            .color(ui_kit::TEXT_WEAK),
                    );
                });
                ui.horizontal(|ui| {
                    ui.add_sized([76.0, 20.0], egui::Label::new("结果单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.scen_result).desired_width(120.0));
                    ui.label(
                        egui::RichText::new("可选；摘要里额外列出这些格子在每个方案下的值")
                            .size(11.0)
                            .color(ui_kit::TEXT_WEAK),
                    );
                });
                if !self.scen_msg.is_empty() {
                    ui.add_space(3.0);
                    ui.label(egui::RichText::new(&self.scen_msg).size(11.5));
                }
                ui_kit::footer(ui, |ui| {
                    if ui.button("添加/修改").clicked() {
                        do_add = true;
                    }
                    if ui.add_enabled(sel.is_some(), egui::Button::new("显示")).clicked() {
                        do_show = true;
                    }
                    if ui.add_enabled(sel.is_some(), egui::Button::new("删除")).clicked() {
                        do_del = true;
                    }
                    if ui.button("摘要").clicked() {
                        do_summary = true;
                    }
                    if ui_kit::primary_button(ui, "关闭").clicked() {
                        self.scen_dlg = false;
                    }
                });
            });
        self.scen_sel = sel;
        if (do_add || do_del) && !self.write_preflight_op(&[], "编辑方案", sheetcore::protection::ProtOp::EditScenarios) {
            self.scen_msg = self.status.clone();
            return;
        }
        let rect = Self::parse_rect(&self.scen_range);
        if do_add {
            match (rect, self.scen_name.trim().is_empty()) {
                (Some(r), false) => {
                    let name = self.scen_name.trim().to_string();
                    let comment = self.scen_comment.trim().to_string();
                    let sc = match sheetcore::scenarios::capture(
                        self.wb.sheet(self.sheet_idx),
                        &name,
                        &comment,
                        r,
                    ) {
                        Ok(sc) => sc,
                        Err(err) => { self.scen_msg = err.to_string(); return; }
                    };
                    let n = sc.cells.len();
                    {
                        let sh = self.wb.sheet_mut(self.sheet_idx);
                        if let Some(existing) = sh.scenarios.iter_mut().find(|x| x.name == name) {
                            if existing.comment != sc.comment || existing.cells != sc.cells {
                                existing.replace_inputs(sc);
                                sh.scenarios_dirty = true;
                                self.wb.dirty = true;
                            }
                        } else {
                            sh.scenarios.push(sc);
                            sh.scenarios_dirty = true;
                            self.wb.dirty = true;
                        }
                    }
                    self.scen_msg = format!("已保存方案「{name}」（{n} 个单元格）");
                    self.status = format!("方案「{name}」已保存");
                }
                (None, _) => self.scen_msg = "可变单元格地址写错了（例如 A1:C3）".into(),
                (_, true) => self.scen_msg = "名称不能为空".into(),
            }
        }
        if do_show && let Some(i) = self.scen_sel {
            self.show_scenario(i);
        }
        if do_del {
            if let Some(i) = self.scen_sel {
                let removed = {
                    let sh = self.wb.sheet_mut(self.sheet_idx);
                    if i < sh.scenarios.len() {
                        let n = sh.scenarios.remove(i).name;
                        sh.scenario_settings.removed(i, sh.scenarios.len());
                        sh.scenarios_dirty = true;
                        Some(n)
                    } else {
                        None
                    }
                };
                if let Some(n) = removed {
                    self.wb.dirty = true;
                    self.scen_sel = None;
                    self.scen_msg = format!("已删除方案「{n}」");
                }
            }
        }
        if do_summary {
            let res = self.scen_result.trim().to_owned();
            match self.build_scenario_summary(&res) {
                Ok(name) => {
                    self.scen_msg = format!("已在「{name}」里生成摘要");
                    self.status = format!("方案摘要已生成：{name}");
                }
                Err(e) => self.scen_msg = e,
            }
        }
        if !open {
            self.scen_dlg = false;
        }
    }

    fn show_scenario(&mut self, index: usize) {
        let sheet_index = self.sheet_idx;
        let Some(sc) = self.wb.sheet(sheet_index).scenarios.get(index).cloned() else { return };
        let mut keys: Vec<_> = sc.cells.iter().map(|(key, _)| *key).collect();
        keys.sort_unstable();
        keys.dedup();
        if !self.write_preflight(&keys, "显示方案") {
            self.scen_msg = self.status.clone();
            return;
        }
        let before = self.txn_begin(&keys);
        let sheet = self.wb.sheet_mut(sheet_index);
        for ((row,col),v) in &sc.cells {
            let cell = sheetcore::Cell { value: sheetcore::scenarios::apply_value(v), formula: None };
            if sheet.get(*row,*col).map(|c| c.into_owned()).unwrap_or_default() != cell {
                sheet.set(*row,*col,cell);
            }
        }
        let deltas = sheetcore::undo::finish(before,sheet);
        if !deltas.is_empty() {
            let changed:Vec<_> = deltas.iter().map(|d|(sheet_index,d.row,d.col)).collect();
            self.record_deltas("显示方案", deltas);
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.wb.dirty = true;
            self.recalc_and_broadcast(&changed);
        }
        self.scen_msg = format!("已显示方案「{}」",sc.name);
        self.status = self.scen_msg.clone();
    }

    /// "A1:C3" / "A1" → (r1, c1, r2, c2)
    fn parse_rect(s: &str) -> Option<(u32, u32, u32, u32)> {
        let t = s.trim();
        if t.is_empty() {
            return None;
        }
        if let Some(r) = sheetcore::table::parse_a1(t) {
            return Some(r);
        }
        parse_a1_ref(t).map(|(r, c)| (r, c, r, c))
    }

    /// 生成「方案摘要」工作表（和 Excel 一样：每行一个方案）。
    /// 带 `results` 时，还会把每个方案下这些格子的计算结果一起写进去。
    fn build_scenario_summary(
        &mut self,
        results: &str,
    ) -> Result<String, String> {
        let list = &self.wb.sheet(self.sheet_idx).scenarios;
        if list.is_empty() {
            return Err("还没有方案，先保存一个".into());
        }
        let mut keys: Vec<_> = list.iter().flat_map(|sc| sc.cells.iter().map(|(key, _)| *key)).collect();
        keys.sort_unstable();
        keys.dedup();
        let mut result_cells = Vec::new();
        for range in results.split_whitespace() {
            let (r1,c1,r2,c2) = Self::parse_rect(range).ok_or_else(|| format!("结果单元格地址无效：{range}"))?;
            for r in r1..=r2 {
                for c in c1..=c2 {
                    if !result_cells.contains(&(r,c)) { result_cells.push((r,c)); }
                    if result_cells.len() > 32 { return Err("每个方案摘要最多可指定 32 个结果单元格".into()); }
                }
            }
        }
        if keys.len() + result_cells.len() + 1 > sheetcore::sync::MAX_COLS as usize
            || list.len() + 2 > sheetcore::sync::MAX_ROWS as usize {
            return Err("方案摘要超过工作表的行列上限".into());
        }
        let mut rows = Vec::new();
        if !result_cells.is_empty() {
            let deps = sheetcore::formula::deps::Deps::build(&self.wb);
            for sc in list {
                let mut preview = self.wb.clone();
                let sheet = preview.sheet_mut(self.sheet_idx);
                for ((r, c), v) in &sc.cells {
                    sheet.set(*r, *c, sheetcore::Cell {
                        value: sheetcore::scenarios::apply_value(v),
                        formula: None,
                    });
                }
                let seeds: Vec<_> = sc.cells.iter().map(|((r, c), _)| (self.sheet_idx, *r, *c)).collect();
                sheetcore::formula::recalc_dirty(&mut preview, &deps, &seeds);
                let values: Vec<_> = result_cells.iter().map(|&(r, c)| preview.sheet(self.sheet_idx).value(r, c)).collect();
                rows.push(values);
            }
        }
        let mut base = "方案摘要".to_string();
        let mut n = 1;
        while self.wb.sheets.iter().any(|s| s.name == base) {
            n += 1;
            base = format!("方案摘要{n}");
        }
        let mut sh = sheetcore::model::Sheet::new(&base);
        let put = |sh: &mut sheetcore::model::Sheet,
                       r: u32,
                       c: u32,
                       v: sheetcore::model::Value| {
            sh.set(
                r,
                c,
                sheetcore::model::Cell {
                    value: v,
                    formula: None,
                },
            );
        };
        put(&mut sh, 0, 0, sheetcore::model::Value::Text("方案摘要".into()));
        for (i, (r, c)) in keys.iter().enumerate() {
            put(
                &mut sh,
                1,
                i as u32 + 1,
                sheetcore::model::Value::Text(cell_name(*r, *c).into()),
            );
        }
        for (j, (r, c)) in result_cells.iter().enumerate() {
            put(
                &mut sh,
                1,
                keys.len() as u32 + j as u32 + 1,
                sheetcore::model::Value::Text(cell_name(*r, *c).into()),
            );
        }
        for (i, sc) in list.iter().enumerate() {
            let row = i as u32 + 2;
            put(&mut sh, row, 0, sheetcore::model::Value::Text(sc.name.clone().into()));
            for (key, text) in &sc.cells {
                let j = keys.binary_search(key).expect("scenario input is in the summary columns");
                put(&mut sh, row, j as u32 + 1, sheetcore::scenarios::apply_value(text));
            }
            for (j, v) in rows.get(i).into_iter().flatten().enumerate() {
                put(
                    &mut sh,
                    row,
                    keys.len() as u32 + j as u32 + 1,
                    v.clone(),
                );
            }
        }
        let idx = self.wb.sheets.len();
        if !sheetcore::sheet_ops::insert_sheet(&mut self.wb, idx, sh) {
            return Err("新建摘要表失败".into());
        }
        self.switch_sheet_view(idx);
        self.sel = (0, 0);
        self.sel_end = (0, 0);
        self.finish_sheet_change();
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        Ok(base)
    }

    fn goal_window(&mut self, ctx: &egui::Context) {
        if !self.goal_dlg {
            return;
        }
        let mut open = true;
        let mut solve = false;
        let mut accept_preview = false;
        let mut revert_preview = false;
        let has_preview = self.goal_preview.is_some();
        ui_kit::window(ctx, "单变量求解", 430.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    ui.add_sized([84.0, 20.0], egui::Label::new("目标单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.goal_target).desired_width(150.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([84.0, 20.0], egui::Label::new("目标值:"));
                    ui.add(egui::TextEdit::singleline(&mut self.goal_goal).desired_width(150.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([84.0, 20.0], egui::Label::new("可变单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.goal_input).desired_width(150.0));
                });
                if !self.goal_msg.is_empty() {
                    ui.add_space(4.0);
                    ui.label(egui::RichText::new(&self.goal_msg).size(11.5));
                }
                ui_kit::footer(ui, |ui| {
                    if has_preview {
                        if ui_kit::primary_button(ui, "接受结果").clicked() {
                            accept_preview = true;
                        }
                        if ui_kit::secondary_button(ui, "还原原值").clicked() {
                            revert_preview = true;
                        }
                    } else {
                        if ui_kit::primary_button(ui, "求解").clicked() {
                            solve = true;
                        }
                        if ui_kit::secondary_button(ui, "取消").clicked() {
                            self.goal_dlg = false;
                        }
                    }
                });
            });
        if accept_preview {
            if let Some((si, vr, vc, orig, found_x, _)) = self.goal_preview.take() {
                let after = self.wb.sheet(si).get(vr, vc).map(|c| c.into_owned()).unwrap_or_default();
                let st_id = self.wb.sheet(si).style_of(vr, vc);
                let delta = sheetcore::undo::CellDelta {
                    sheet: si,
                    row: vr,
                    col: vc,
                    before: orig.unwrap_or_default(),
                    after,
                    before_style: st_id,
                    after_style: st_id,
                };
                self.record_deltas("单变量求解", vec![delta]);
                self.wb.dirty = true;
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.status = format!("已接受单变量求解：{} = {:.6}", sheetcore::model::cell_name(vr, vc), found_x);
                self.goal_dlg = false;
            }
            return;
        }
        if revert_preview || (!open && self.goal_preview.is_some()) {
            if let Some((si, vr, vc, orig, _, _)) = self.goal_preview.take() {
                let sh = self.wb.sheet_mut(si);
                match orig {
                    Some(c) => sh.set(vr, vc, c),
                    None => {
                        sh.remove(vr, vc);
                    }
                }
                self.recalc_all_and_deps_adaptive();
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.goal_msg = "已还原可变单元格原值".into();
                self.status = "单变量求解已取消并还原原值".into();
            }
            if !open {
                self.goal_dlg = false;
            }
            return;
        }
        if solve {
            let t = Self::parse_addr(&self.goal_target);
            let v = Self::parse_addr(&self.goal_input);
            let goal = self.goal_goal.trim().parse::<f64>();
            match (t, v, goal) {
                (Some((tr, tc)), Some((vr, vc)), Ok(g)) => {
                    let big_wb = !cfg!(test)
                        && self.wb.sheets.iter().map(|s| s.len()).sum::<usize>() > 2_000;
                    if big_wb {
                        let Some(orig) = self.cell_num(vr, vc) else {
                            self.goal_msg = "可变单元格里必须是一个数字".into();
                            return;
                        };
                        let uid = self.doc_uid;
                        let si = self.sheet_idx;
                        let mut wb_bg = self.wb.clone();
                        let deps_bg = if self.deps_built {
                            std::sync::Arc::new(self.deps.fork_isolated())
                        } else {
                            std::sync::Arc::new(sheetcore::formula::deps::Deps::build(&wb_bg))
                        };
                        let (tx, rx) = std::sync::mpsc::channel();
                        self.bg_goal_seek_rx = Some(rx);
                        self.goal_msg = "正在后台迭代求解…".into();
                        self.status = "正在后台执行单变量求解…".into();
                        let wake = ctx.clone();
                        std::thread::spawn(move || {
                            let eval = |wb: &mut Workbook, x: f64| -> Option<f64> {
                                wb.sheet_mut(si).set(
                                    vr,
                                    vc,
                                    Cell {
                                        value: Value::Number(x),
                                        formula: None,
                                    },
                                );
                                sheetcore::formula::recalc_dirty(wb, &deps_bg, &[(si, vr, vc)]);
                                match wb.sheet(si).value(tr, tc) {
                                    Value::Number(v) => Some(v - g),
                                    _ => None,
                                }
                            };
                            let res = (|| -> Result<f64, String> {
                                let mut x0 = orig;
                                let mut f0 = eval(&mut wb_bg, x0)
                                    .ok_or_else(|| "目标单元格不是数字（公式可能出错）".to_string())?;
                                if f0.abs() < 1e-9 {
                                    return Ok(x0);
                                }
                                let step = if x0.abs() > 1e-9 { x0.abs() * 0.1 } else { 1.0 };
                                let mut x1 = x0 + step;
                                let mut f1 = eval(&mut wb_bg, x1)
                                    .ok_or_else(|| "目标单元格不是数字".to_string())?;
                                let mut lo = f64::NAN;
                                let mut hi = f64::NAN;
                                for _ in 0..60 {
                                    if f1.abs() < 1e-9 {
                                        return Ok(x1);
                                    }
                                    if f0.abs() < 1e-9 {
                                        return Ok(x0);
                                    }
                                    if f0 * f1 < 0.0 {
                                        lo = x0;
                                        hi = x1;
                                    }
                                    let denom = f1 - f0;
                                    let mut next = if denom.abs() > 1e-15 {
                                        x1 - f1 * (x1 - x0) / denom
                                    } else {
                                        f64::NAN
                                    };
                                    if !next.is_finite()
                                        || (lo.is_finite()
                                            && hi.is_finite()
                                            && (next < lo.min(hi) || next > lo.max(hi)))
                                    {
                                        next = if lo.is_finite() && hi.is_finite() {
                                            (lo + hi) * 0.5
                                        } else {
                                            x1 + step
                                        };
                                    }
                                    x0 = x1;
                                    f0 = f1;
                                    x1 = next;
                                    f1 = eval(&mut wb_bg, x1)
                                        .ok_or_else(|| "目标单元格不是数字".to_string())?;
                                    if (x1 - x0).abs() < 1e-12 * (1.0 + x1.abs()) {
                                        break;
                                    }
                                }
                                if f1.abs() < 1e-6 {
                                    Ok(x1)
                                } else {
                                    Err(format!("没有找到解（最后一次偏差 {f1:.6}）"))
                                }
                            })();
                            let _ = tx.send((uid, si, tr, tc, vr, vc, res));
                            wake.request_repaint();
                        });
                    } else {
                        let si = self.sheet_idx;
                        let orig_cell = self.wb.sheet(si).get(vr, vc).map(|c| c.into_owned());
                        match self.goal_seek_run(tr, tc, g, vr, vc) {
                            Ok(x) => {
                                let achieved = match self.wb.sheet(si).value(tr, tc) {
                                    Value::Number(v) => v,
                                    _ => g,
                                };
                                self.goal_preview = Some((si, vr, vc, orig_cell, x, achieved));
                                self.goal_msg = format!(
                                    "求解预览：{} = {:.6}（目标值 {:.6}，当前值 {:.6}）。请点击「接受结果」或「还原原值」。",
                                    sheetcore::model::cell_name(vr, vc),
                                    x,
                                    g,
                                    achieved
                                );
                                self.doc_gen = self.doc_gen.wrapping_add(1);
                                self.status = format!("单变量求解预览：{} = {:.6}", sheetcore::model::cell_name(vr, vc), x);
                            }
                            Err(e) => self.goal_msg = e,
                        }
                    }
                }
                _ => self.goal_msg = "单元格地址或目标值写错了".into(),
            }
        }
        if !open {
            self.goal_dlg = false;
        }
    }

    /// 模拟运算表（列式单变量）：选区第一列是输入值，第二列顶行是公式，
    /// 按每个输入值代入后把结果填到第二列。
    /// 模拟运算表：列式单变量 / 行式单变量 / 双变量三种版式，按选区形状自动判断。
    /// - 双变量：公式在选区左上角，第一行是行输入值，第一列是列输入值
    /// - 列式单变量：公式在选区右上格的上方，第一列是输入值、第二列出结果
    /// - 行式单变量：公式在选区左下格的左边，第一行是输入值、第二行出结果
    fn data_table_run(
        &mut self,
        row_in: Option<(u32, u32)>,
        col_in: Option<(u32, u32)>,
    ) -> Result<(String, usize), String> {
        let (r1, c1, r2, c2) = self.sel_rect();
        let has_formula = |app: &Self, r: i64, c: i64| -> bool {
            if r < 0 || c < 0 {
                return false;
            }
            app.wb
                .sheet(app.sheet_idx)
                .get(r as u32, c as u32)
                .and_then(|x| x.formula.clone())
                .is_some()
        };
        // 判定版式
        let mode = if has_formula(self, r1 as i64, c1 as i64) && c2 > c1 && r2 > r1 {
            "two"
        } else if has_formula(self, r1 as i64 - 1, c2 as i64) {
            "col"
        } else if has_formula(self, r1 as i64 + 1, c1 as i64) {
            "row"
        } else {
            return Err(
                "认不出版式：双变量要求公式在选区左上角；                  单变量（列）要求公式在结果列上方；                 单变量（行）要求公式在结果行左侧"
                    .into(),
            );
        };
        let need_row = mode == "row" || mode == "two";
        let need_col = mode == "col" || mode == "two";
        if need_row && row_in.is_none() {
            return Err("这个版式需要「行输入引用单元格」".into());
        }
        if need_col && col_in.is_none() {
            return Err("这个版式需要「列输入引用单元格」".into());
        }
        let est_cells: u64 = match mode {
            "two" => (r2.saturating_sub(r1) as u64) * (c2.saturating_sub(c1) as u64),
            "col" => (r2.saturating_sub(r1) + 1) as u64,
            _ => c2.saturating_sub(c1) as u64,
        };
        if est_cells > 5_000 {
            return Err("模拟运算表输出区域超过 5000 个单元格上限，请缩小选区范围".into());
        }
        let (fcell, results_src): ((u32, u32), Vec<(u32, u32, Option<f64>, Option<f64>)>) = match mode {
            "two" => {
                let mut cells = Vec::new();
                for r in (r1 + 1)..=r2 {
                    for c in (c1 + 1)..=c2 {
                        // Excel 双变量模拟运算表：首行 (r1, c) 填行输入单元格，首列 (r, c1) 填列输入单元格
                        let rv = self.cell_num(r1, c);
                        let cv = self.cell_num(r, c1);
                        cells.push((r, c, rv, cv));
                    }
                }
                ((r1, c1), cells)
            }
            "col" => {
                let mut cells = Vec::new();
                for r in r1..=r2 {
                    let cv = self.cell_num(r, c1);
                    cells.push((r, c2, None, cv));
                }
                ((r1 - 1, c2), cells)
            }
            _ => {
                let mut cells = Vec::new();
                for c in (c1 + 1)..=c2 {
                    let rv = self.cell_num(r1, c);
                    cells.push((r1 + 1, c, rv, None));
                }
                ((r1 + 1, c1), cells)
            }
        };
        if results_src.iter().all(|(_, _, rv, cv)| rv.is_none() && cv.is_none()) {
            return Err("选区里没有可用的输入值".into());
        }
        // 写入动态 `{=TABLE(row_in, col_in)}` 公式并登记到 `sheet.arrays`，支持输入/源公式变更后自动重算！
        let (out_rect, table_formula) = match mode {
            "two" => {
                let r_ref = row_in.map(|(r, c)| cell_name(r, c)).unwrap_or_default();
                let c_ref = col_in.map(|(r, c)| cell_name(r, c)).unwrap_or_default();
                ((r1 + 1, c1 + 1, r2, c2), format!("=TABLE({r_ref},{c_ref})"))
            }
            "col" => {
                let c_ref = col_in.map(|(r, c)| cell_name(r, c)).unwrap_or_default();
                ((r1, c1 + 1, r2, c2), format!("=TABLE(,{c_ref})"))
            }
            _ => {
                let r_ref = row_in.map(|(r, c)| cell_name(r, c)).unwrap_or_default();
                ((r1 + 1, c1 + 1, r2, c2), format!("=TABLE({r_ref},)"))
            }
        };
        let (or1, oc1, or2, oc2) = out_rect;
        let si = self.sheet_idx;
        let out_keys = sheetcore::undo::rect_keys(or1, oc1, or2, oc2);
        let before_cells = sheetcore::undo::capture(self.wb.sheet(si), si, &out_keys);
        let before_arrays = self.wb.sheet(si).arrays.clone();
        let mut done = 0usize;
        let f_arc: std::sync::Arc<str> = table_formula.into();
        {
            let sh = self.wb.sheet_mut(si);
            for r in or1..=or2 {
                for c in oc1..=oc2 {
                    sh.set(
                        r,
                        c,
                        Cell {
                            value: Value::Empty,
                            formula: Some(f_arc.clone()),
                        },
                    );
                    done += 1;
                }
            }
            let anchor = sheetcore::model::CellRef::new(or1, oc1);
            sh.arrays.retain(|(a, _)| *a != anchor);
            sh.arrays.push((anchor, out_rect));
        }
        sheetcore::formula::eval_data_tables_in_workbook(&mut self.wb, None);
        let after_arrays = self.wb.sheet(si).arrays.clone();
        let deltas = sheetcore::undo::finish(before_cells, self.wb.sheet(si));
        self.undo.push_with_arrays(
            sheetcore::undo::Action {
                label: "模拟运算表".into(),
                merges: None,
                deltas,
                focus: (si, or1, oc1),
                snap_before: None,
                snap_after: None,
                by_site: 0,
                pictures: None,
                shapes: None,
                refresh_sizes: None,
            },
            Some(sheetcore::undo::ArrayEdit {
                sheet: si,
                before: before_arrays,
                after: after_arrays,
            }),
        );
        self.deps = sheetcore::formula::deps::Deps::build_after_recalc(&self.wb).into();
        self.deps_built = true;
        let _ = (fcell, results_src);
        let label = match mode {
            "two" => "双变量动态模拟运算表",
            "col" => "单变量（列）动态模拟运算表",
            _ => "单变量（行）动态模拟运算表",
        };
        Ok((label.to_string(), done))
    }

    fn dtable_window(&mut self, ctx: &egui::Context) {
        if !self.dtable_dlg {
            return;
        }
        let mut open = true;
        let mut run = false;
        ui_kit::window(ctx, "模拟运算表", 480.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(
                    egui::RichText::new(
                        "双变量：公式在选区左上角，首行是行输入值、首列是列输入值。
                         单变量（列）：公式在结果列上方，第一列是输入值。
                         单变量（行）：公式在结果行左侧，第一行是输入值。",
                    )
                    .size(11.5)
                    .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(4.0);
                ui.horizontal(|ui| {
                    ui.add_sized([110.0, 20.0], egui::Label::new("行输入单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.dtable_row).desired_width(120.0));
                });
                ui.horizontal(|ui| {
                    ui.add_sized([110.0, 20.0], egui::Label::new("列输入单元格:"));
                    ui.add(egui::TextEdit::singleline(&mut self.dtable_col).desired_width(120.0));
                });
                if !self.dtable_msg.is_empty() {
                    ui.add_space(4.0);
                    ui.label(egui::RichText::new(&self.dtable_msg).size(11.5));
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        run = true;
                    }
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        self.dtable_dlg = false;
                    }
                });
            });
        if run {
            let rin = if self.dtable_row.trim().is_empty() {
                None
            } else {
                Self::parse_addr(&self.dtable_row)
            };
            let cin = if self.dtable_col.trim().is_empty() {
                None
            } else {
                Self::parse_addr(&self.dtable_col)
            };
            match self.data_table_run(rin, cin) {
                Ok((label, n)) => {
                    self.dtable_msg = format!("{label}：已填 {n} 个结果");
                    self.wb.dirty = true;
                    self.doc_gen = self.doc_gen.wrapping_add(1);
                    self.status = format!("模拟运算表（{label}）：已填 {n} 个结果");
                }
                Err(e) => self.dtable_msg = e,
            }
        }
        if !open {
            self.dtable_dlg = false;
        }
    }

    fn symbol_window(&mut self, ctx: &egui::Context) {
        if !self.symbol_dlg {
            return;
        }
        let mut open = true;
        let mut insert: Option<char> = None;
        ui_kit::window(ctx, "符号", 430.0)
            .open(&mut open)
            .show(ctx, |ui| {
                ui.label(
                    egui::RichText::new("点一个符号就插到当前单元格")
                        .size(11.5)
                        .color(ui_kit::TEXT_WEAK),
                );
                ui.add_space(4.0);
                let cats: [(&str, &[&str]); 6] = [
                    (
                        "常用",
                        &[
                            "×", "÷", "±", "≈", "≠", "≤", "≥", "∞", "√", "∑",
                            "∏", "∫", "°", "′", "″", "℃", "¥", "$", "€", "£",
                            "‰", "§", "¶", "※",
                        ],
                    ),
                    (
                        "箭头",
                        &[
                            "←", "↑", "→", "↓", "↔", "↕", "⇐", "⇒",
                            "⇔", "▲", "▼", "◀", "▶", "△", "▽",
                        ],
                    ),
                    (
                        "数学",
                        &[
                            "∀", "∂", "∃", "∅", "∇", "∈", "∉", "∋", "∝", "∠",
                            "⊥", "∥", "∩", "∪", "⊂", "⊃", "⊆", "⊇", "⊕", "⊗",
                        ],
                    ),
                    (
                        "希腊",
                        &[
                            "α", "β", "γ", "δ", "ε", "ζ", "η", "θ", "ι", "κ",
                            "λ", "μ", "ν", "ξ", "π", "ρ", "σ", "τ", "υ", "φ",
                            "χ", "ψ", "ω", "Δ", "Ω", "Σ", "Π", "Λ", "Θ", "Φ",
                        ],
                    ),
                    (
                        "图形",
                        &[
                            "●", "○", "◆", "◇", "■", "□", "★", "☆", "♀", "♂",
                            "♪", "♫", "♠", "♣", "♥", "♦", "✓", "✗",
                        ],
                    ),
                    (
                        "编号",
                        &[
                            "①", "②", "③", "④", "⑤", "⑥", "⑦", "⑧", "⑨", "⑩",
                            "Ⅰ", "Ⅱ", "Ⅲ", "Ⅳ", "Ⅴ", "½", "¼", "¾",
                        ],
                    ),
                ];
                egui::ScrollArea::vertical().max_height(320.0).show(ui, |ui| {
                    for (name, list) in cats {
                        ui.label(egui::RichText::new(name).font(ui_kit::bold(ui_kit::T_BODY)));
                        ui.horizontal_wrapped(|ui| {
                            ui.spacing_mut().item_spacing = egui::vec2(2.0, 2.0);
                            for sy in list {
                                if ui
                                    .add_sized(
                                        [26.0, 26.0],
                                        egui::Button::new(egui::RichText::new(*sy).size(14.0)),
                                    )
                                    .on_hover_text(*sy)
                                    .clicked()
                                {
                                    insert = sy.chars().next();
                                }
                            }
                        });
                        ui.add_space(8.0);
                    }
                });
            });
        if let Some(ch) = insert {
            self.insert_symbol(ch);
            self.status = format!("已插入 {ch}");
        }
        if !open {
            self.symbol_dlg = false;
        }
    }

    /// 应用右上角账户窗口里的显示名。
    ///
    /// 名字同时用于协作光标、编辑占用卡、修订记录和本机 UI；改名后立即广播给
    /// 在线参与者，下一次启动从 ui.ini 恢复。空名字不覆盖当前值。
    fn apply_display_name(&mut self, raw: &str) -> bool {
        let name = clean_user_name(raw);
        if name.is_empty() {
            self.profile_msg = "显示名称不能为空".into();
            return false;
        }
        if name == self.my_name {
            self.profile_msg.clear();
            self.status = "显示名称未改变".into();
            return true;
        }
        self.my_name = name.clone();
        self.prefs.user_name = name.clone();
        self.prefs.save();
        // 名字变了，下一帧必须重发光标，否则别人看到的还是旧名字。
        self.last_cursor = None;
        if let Some(me) = self.peer.as_ref().map(|p| p.site) {
            if let Some(e) = self.peers_list.iter_mut().find(|e| e.0 == me) {
                e.1 = name.clone();
            }
        }
        let hosting = self.net.as_ref().map(|n| n.hosting).unwrap_or(false);
        if let Some(net) = self.net.as_ref() {
            net.rename(&name);
        }
        // 宿主刷新占用卡，后加入的人从卡里读到的也是新名字。
        if hosting {
            if let (Some(path), Some(net)) = (self.wb.path.clone(), self.net.as_ref()) {
                let ips = session_lock::local_lan_ips();
                let addr = format!("{}:{}", ips[0], net.port);
                let hosts: Vec<String> = ips.iter().map(|ip| format!("{ip}:{}", net.port)).collect();
                let _ = session_lock::write_session_with_hosts(
                    &path,
                    &addr,
                    &hosts,
                    &self.my_name,
                    &net.session_id,
                    net.started_ms,
                    &net.lock_secret,
                );
                session_lock::refresh_election(&path, &net.session_id);
                self.lock_beat = Some(std::time::Instant::now());
            }
        }
        self.profile_msg.clear();
        self.status = format!("显示名称已改为「{name}」");
        true
    }

    /// 右上角账户窗口：设置本机在协作/修订里显示的名字。
    fn account_window(&mut self, ctx: &egui::Context) {
        if !self.profile_open {
            return;
        }
        let mut open = true;
        let mut save = false;
        let mut about = false;
        let initial = self
            .my_name
            .chars()
            .next()
            .unwrap_or('U')
            .to_uppercase()
            .to_string();
        ui_kit::window(ctx, "账户与本机身份", 440.0)
            .open(&mut open)
            .show(ctx, |ui| {
                let pal = theme::palette();
                let card_w = ui.available_width();
                let (card_r, _) = ui.allocate_exact_size(Vec2::new(card_w, 58.0), Sense::hover());
                let p = ui.painter();
                p.rect(
                    card_r,
                    8.0,
                    pal.card_bg,
                    Stroke::new(1.0, pal.card_border),
                    egui::StrokeKind::Inside,
                );
                let ac = egui::pos2(card_r.left() + 30.0, card_r.center().y);
                p.circle_filled(ac, 20.5, pal.accent_tint);
                p.circle_filled(ac, 17.5, ui_kit::BRAND_NAVY);
                p.text(
                    ac,
                    egui::Align2::CENTER_CENTER,
                    &initial,
                    ui_kit::ui_bold_in(ctx, 14.5),
                    Color32::WHITE,
                );
                let name_clip = Rect::from_min_max(
                    egui::pos2(card_r.left() + 60.0, card_r.top() + 8.0),
                    egui::pos2(card_r.right() - 14.0, card_r.bottom() - 8.0),
                );
                let cur_disp = Self::elide(&self.my_name, 30);
                p.with_clip_rect(name_clip.intersect(p.clip_rect())).text(
                    egui::pos2(card_r.left() + 60.0, card_r.center().y),
                    egui::Align2::LEFT_CENTER,
                    &cur_disp,
                    ui_kit::medium_in(ctx, 14.0),
                    pal.text,
                );

                ui.add_space(6.0);
                let (lbl_r, _) = ui.allocate_exact_size(Vec2::new(card_w, 18.0), Sense::hover());
                ui_kit::paint_medium(
                    ui.painter(),
                    egui::pos2(lbl_r.left(), lbl_r.center().y),
                    egui::Align2::LEFT_CENTER,
                    "显示名称",
                    12.5,
                    pal.text,
                );
                let resp = ui_kit::text_input(ui, &mut self.profile_draft, "输入显示名称");
                if resp.lost_focus() && ui.input(|i| i.key_pressed(egui::Key::Enter)) {
                    save = true;
                }
                if !self.profile_msg.is_empty() {
                    ui.colored_label(pal.err_fg, &self.profile_msg);
                }
                if ui.input(|i| i.key_pressed(egui::Key::Escape)) {
                    open = false;
                }
                ui_kit::footer_split(
                    ui,
                    |ui| {
                        let ab_txt = format!("关于 {} v{}", update::APP_NAME, update::VERSION);
                        let ab_font = ui_kit::medium_in(ui.ctx(), 12.0);
                        let tw = ui
                            .painter()
                            .layout_no_wrap(ab_txt.clone(), ab_font.clone(), Color32::PLACEHOLDER)
                            .size()
                            .x;
                        let (ab_r, ab_resp) =
                            ui.allocate_exact_size(Vec2::new(tw + 38.0, 30.0), Sense::click());
                        if ab_resp.hovered() {
                            ui.painter().rect_filled(ab_r, 6.0, pal.hover);
                            ui.ctx().set_cursor_icon(egui::CursorIcon::PointingHand);
                        }
                        ui_kit::draw_brand_logo(
                            ui.painter(),
                            Rect::from_center_size(
                                egui::pos2(ab_r.left() + 15.0, ab_r.center().y),
                                Vec2::splat(15.0),
                            ),
                        );
                        ui.painter().text(
                            egui::pos2(ab_r.left() + 29.0, ab_r.center().y),
                            egui::Align2::LEFT_CENTER,
                            ab_txt,
                            ab_font,
                            pal.text_weak,
                        );
                        if ab_resp.clicked() {
                            about = true;
                        }
                    },
                    |ui| {
                        if ui_kit::primary_button(ui, "保存").clicked() {
                            save = true;
                        }
                        if ui_kit::secondary_button(ui, "取消").clicked() {
                            open = false;
                        }
                    },
                );
            });
        let draft = self.profile_draft.clone();
        if save && self.apply_display_name(&draft) {
            self.profile_open = false;
        }
        if about {
            self.profile_open = false;
            self.about_open = true;
        }
        if !open {
            self.profile_open = false;
        }
    }

