    /// 名称管理器：列出/新建/修改/删除定义名称
    fn name_manager_window(&mut self, ctx: &egui::Context) {
        if !self.name_mgr {
            return;
        }
        let mut open = self.name_mgr;
        let mut close = false;
        let mut del: Option<usize> = None;
        let mut start_edit: Option<usize> = None;
        let mut submit = false;
        let rows: Vec<(String, String)> = self
            .wb
            .names
            .iter()
            .map(|(name, sheet, refers)| {
                let scope = sheet
                    .and_then(|s| self.wb.sheets.get(s))
                    .map(|x| x.name.clone())
                    .unwrap_or_else(|| "工作簿".into());
                (name.clone(), format!("{refers}  （{scope}）"))
            })
            .collect();
        ui_kit::window(ctx, "名称管理器", 520.0)
            .open(&mut open)
            .resizable(true)
            .show(ctx, |ui| {
                egui::ScrollArea::vertical().max_height(220.0).show(ui, |ui| {
                    egui::Grid::new("nm_grid").striped(true).num_columns(3).show(ui, |ui| {
                        ui.strong("名称");
                        ui.strong("引用位置");
                        ui.strong("");
                        ui.end_row();
                        for (i, (name, refers)) in rows.iter().enumerate() {
                            ui.label(name);
                            ui.label(refers);
                            ui.horizontal(|ui| {
                                if ui.small_button("编辑").clicked() {
                                    start_edit = Some(i);
                                }
                                if ui.small_button("删除").clicked() {
                                    del = Some(i);
                                }
                            });
                            ui.end_row();
                        }
                    });
                });
                ui.separator();
                ui.horizontal(|ui| {
                    ui.label("名称");
                    ui.add(egui::TextEdit::singleline(&mut self.name_new).desired_width(120.0));
                    ui.label("引用");
                    ui.add(egui::TextEdit::singleline(&mut self.name_refers).desired_width(200.0));
                    ui.checkbox(&mut self.name_scope_local, "仅当前工作表");
                    if ui.button(if self.name_edit_idx.is_some() { "保存" } else { "新建" }).clicked() {
                        submit = true;
                    }
                });
                if !self.name_err.is_empty() {
                    ui.colored_label(egui::Color32::from_rgb(190, 40, 40), &self.name_err);
                }
                ui.weak("引用写法：Sheet1!$A$1:$B$3，或常量 ={\"甲\";\"乙\"}");
                ui_kit::footer(ui, |ui| {
                    if ui_kit::secondary_button(ui, "关闭").clicked() {
                        close = true;
                    }
                });
            });
        self.name_mgr = open && !close;
        if let Some(i) = start_edit {
            let item = self.wb.names.get(i).cloned();
            if let Some((name, sheet, refers)) = item {
                self.name_new = name;
                self.name_refers = refers;
                self.name_scope_local = sheet == Some(self.sheet_idx);
                self.name_edit_idx = Some(i);
            }
        }
        if let Some(i) = del {
            if i < self.wb.names.len() {
                let before_names = self.wb.names.clone();
                self.wb.names.remove(i);
                let after_names = self.wb.names.clone();
                self.undo.push_meta(
                    "删除名称",
                    (self.sheet_idx, self.sel.0, self.sel.1),
                    sheetcore::undo::MetaEdit {
                        sheet: self.sheet_idx,
                        names: Some((before_names, after_names)),
                        ..Default::default()
                    },
                );
                self.wb.names_dirty = true;
                self.wb.dirty = true;
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.recalc_all_and_deps_adaptive();
                self.status = "已删除名称".into();
            }
        }
        if submit {
            let name = self.name_new.trim().to_string();
            let refers = self.name_refers.trim().to_string();
            let valid = Self::valid_defined_name(&name) && self.valid_name_refers(&refers);
            let dup = self
                .wb
                .names
                .iter()
                .enumerate()
                .any(|(k, (n, sh, _))| {
                    k != self.name_edit_idx.unwrap_or(usize::MAX)
                        && n.eq_ignore_ascii_case(&name)
                        && *sh == if self.name_scope_local { Some(self.sheet_idx) } else { None }
                });
            if !valid {
                self.name_err = "名称要以字母/下划线开头且不能是 A1/R1C1；引用要写成 Sheet1!$A$1:$B$3、={...} 或 =SUM(...)".into();
            } else if dup {
                self.name_err = "名称已存在".into();
            } else {
                self.name_err.clear();
                let before_names = self.wb.names.clone();
                match self.name_edit_idx.take() {
                    Some(i) if i < self.wb.names.len() => {
                        self.wb.names[i].0 = name;
                        self.wb.names[i].1 = if self.name_scope_local { Some(self.sheet_idx) } else { None };
                        self.wb.names[i].2 = refers;
                    }
                    _ => self.wb.names.push((
                        name,
                        if self.name_scope_local { Some(self.sheet_idx) } else { None },
                        refers,
                    )),
                }
                let after_names = self.wb.names.clone();
                self.undo.push_meta(
                    "编辑名称",
                    (self.sheet_idx, self.sel.0, self.sel.1),
                    sheetcore::undo::MetaEdit {
                        sheet: self.sheet_idx,
                        names: Some((before_names, after_names)),
                        ..Default::default()
                    },
                );
                self.wb.names_dirty = true;
                self.wb.dirty = true;
                self.name_new.clear();
                self.name_refers.clear();
                self.doc_gen = self.doc_gen.wrapping_add(1);
                self.recalc_all_and_deps_adaptive();
                self.status = "名称已保存".into();
            }
        }
    }

    /// 工作表保护：设置/撤销密码
    fn protect_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut d) = self.protect_dlg.take() else { return };
        let mut open = true;
        let mut apply = false;
        let title = if d.unprotect { "撤销工作表保护" } else { "保护工作表" };
        ui_kit::window(ctx, title, 320.0).open(&mut open).show(ctx, |ui| {
            ui.add_space(4.0);
            ui.label(if d.unprotect {
                "输入保护密码（没有密码直接确定）"
            } else {
                "设置密码后，锁定单元格将不能编辑；留空表示只防误改、不设密码"
            });
            ui.add_space(6.0);
            ui.horizontal(|ui| {
                ui.label("密码");
                ui.add(
                    egui::TextEdit::singleline(&mut d.pw)
                        .password(true)
                        .desired_width(180.0),
                );
            });
            if !d.unprotect {
                ui.horizontal(|ui| {
                    ui.label("确认");
                    ui.add(
                        egui::TextEdit::singleline(&mut d.confirm)
                            .password(true)
                            .desired_width(180.0),
                    );
                });
                ui.add_space(6.0);
                ui.label(egui::RichText::new("允许此工作表的所有用户进行：").strong());
                egui::ScrollArea::vertical()
                    .max_height(180.0)
                    .show(ui, |ui| {
                        use sheetcore::protection::ProtPerms as P;
                        let mut row = |ui: &mut egui::Ui, label: &str, v: &mut bool| {
                            ui.checkbox(v, label);
                        };
                        let P {
                            select_locked,
                            select_unlocked,
                            format_cells,
                            format_columns,
                            format_rows,
                            insert_columns,
                            insert_rows,
                            delete_columns,
                            delete_rows,
                            insert_links,
                            sort,
                            auto_filter,
                            pivot_tables,
                            edit_objects,
                            edit_scenarios,
                        } = &mut d.perms;
                        row(ui, "选定锁定单元格", select_locked);
                        row(ui, "选定未锁定的单元格", select_unlocked);
                        row(ui, "设置单元格格式", format_cells);
                        row(ui, "设置列格式", format_columns);
                        row(ui, "设置行格式", format_rows);
                        row(ui, "插入列", insert_columns);
                        row(ui, "插入行", insert_rows);
                        row(ui, "删除列", delete_columns);
                        row(ui, "删除行", delete_rows);
                        row(ui, "插入超链接", insert_links);
                        row(ui, "排序", sort);
                        row(ui, "使用自动筛选", auto_filter);
                        row(ui, "使用数据透视表", pivot_tables);
                        row(ui, "编辑对象", edit_objects);
                        row(ui, "编辑方案", edit_scenarios);
                    });
                ui.separator();
                ui.label(egui::RichText::new("允许编辑区域（ProtectedRanges）").strong());
                let cur_rect = self.sel_rect();
                let mut add_pr = false;
                let mut del_pr: Option<usize> = None;
                ui.horizontal(|ui| {
                    ui.add(
                        egui::TextEdit::singleline(&mut d.new_range_title)
                            .hint_text("区域名称（留空自动命名）")
                            .desired_width(150.0),
                    );
                    if ui.small_button("添加当前选区").clicked() {
                        add_pr = true;
                    }
                });
                let existing_prs: Vec<(String, String)> = self
                    .wb
                    .sheet(self.sheet_idx)
                    .protected_ranges
                    .iter()
                    .map(|pr| (pr.title.clone(), pr.sqref_string()))
                    .collect();
                for (i, (t, sq)) in existing_prs.iter().enumerate() {
                    ui.horizontal(|ui| {
                        ui.label(format!("{t}: {sq}"));
                        if ui.small_button("删除").clicked() {
                            del_pr = Some(i);
                        }
                    });
                }
                if add_pr {
                    let sh = self.wb.sheet_mut(self.sheet_idx);
                    let title = if d.new_range_title.trim().is_empty() {
                        format!("区域{}", sh.protected_ranges.len() + 1)
                    } else {
                        d.new_range_title.trim().to_string()
                    };
                    sh.protected_ranges.push(sheetcore::protection::ProtectedRange::new(
                        title,
                        vec![cur_rect],
                        "",
                    ));
                    sh.protected_ranges_dirty = true;
                    d.new_range_title.clear();
                    self.wb.dirty = true;
                }
                if let Some(i) = del_pr {
                    let sh = self.wb.sheet_mut(self.sheet_idx);
                    if i < sh.protected_ranges.len() {
                        sh.protected_ranges.remove(i);
                        sh.protected_ranges_dirty = true;
                        self.wb.dirty = true;
                    }
                }
            }
            ui.separator();
            ui.checkbox(&mut d.lock_wb_structure, "保护工作簿结构（禁止增删/改名/移动/隐藏工作表）");
            if d.lock_wb_structure {
                ui.horizontal(|ui| {
                    ui.label("工作簿密码");
                    ui.add(
                        egui::TextEdit::singleline(&mut d.wb_pw)
                            .password(true)
                            .hint_text("可选")
                            .desired_width(150.0),
                    );
                });
            }
            if !d.err.is_empty() {
                ui.colored_label(egui::Color32::from_rgb(200, 60, 60), &d.err);
            }
            ui_kit::footer(ui, |ui| {
                if ui_kit::primary_button(ui, "确定").clicked() {
                    apply = true;
                }
                if ui_kit::secondary_button(ui, "取消").clicked() {
                    open = false;
                }
            });
        });
        if apply {
            if !d.unprotect && d.pw != d.confirm {
                d.err = "两次输入的密码不一致".into();
                self.protect_dlg = Some(d);
                return;
            }
            // 先校验工作簿结构保护解锁（若原先有密码保护）
            if !d.lock_wb_structure {
                if let Some(wp) = &self.wb.protection {
                    if wp.has_password() && !wp.verify(&d.wb_pw) && !wp.verify(&d.pw) {
                        d.err = "撤销工作簿结构保护密码不正确".into();
                        self.protect_dlg = Some(d);
                        return;
                    }
                    self.wb.protection = None;
                    self.wb.protection_dirty = true;
                    self.wb.dirty = true;
                }
            } else if self.wb.protection.is_none() || !d.wb_pw.is_empty() {
                self.wb.protection = Some(sheetcore::protection::WorkbookProtection::new_with_password(
                    &d.wb_pw, true, false,
                ));
                self.wb.protection_dirty = true;
                self.wb.dirty = true;
            }
            let sh = self.wb.sheet_mut(self.sheet_idx);
            if d.unprotect {
                let ok = sh
                    .protection
                    .as_ref()
                    .map(|p| p.verify(&d.pw))
                    .unwrap_or(false);
                if !ok {
                    d.err = "密码不正确".into();
                    self.protect_dlg = Some(d);
                    return;
                }
                sh.protection = None;
                sh.protect_dirty = true;
                self.wb.dirty = true;
                self.status = "已撤销工作表保护".into();
            } else {
                let mut p = sheetcore::protection::SheetProtection::new_with_password(&d.pw);
                p.perms = d.perms;
                // objects/scenarios 与「编辑对象/编辑方案」是同一件事的两种写法
                p.objects = !d.perms.edit_objects;
                p.scenarios = !d.perms.edit_scenarios;
                sh.protection = Some(p);
                sh.protect_dirty = true;
                self.wb.dirty = true;
                self.status = "工作表已保护".into();
            }
            open = false;
        }
        if open {
            self.protect_dlg = Some(d);
        }
    }

    // ---------------------------------------------------------------- 工作表视图 / 窗口

    fn views_key(&self) -> String {
        self.wb
            .path
            .as_ref()
            .map(|p| p.to_string_lossy().to_string())
            .unwrap_or_default()
    }

    /// 把当前缩放/冻结/选区存成一个命名视图
    fn view_capture(&self, name: &str) -> ui_prefs::SavedView {
        ui_prefs::SavedView {
            name: name.to_string(),
            sheet: self.sheet_idx,
            zoom: self.zoom,
            freeze: self.wb.sheet(self.sheet_idx).freeze,
            sel: self.sel,
        }
    }

    /// 应用一个视图
    fn view_apply(&mut self, idx: usize) {
        let Some(v) = self.views.get(idx).cloned() else { return };
        let target = v.sheet.min(self.wb.sheets.len().saturating_sub(1));
        if target != self.sheet_idx && !self.switch_sheet_view(target) {
            return;
        }
        self.zoom = v.zoom.clamp(0.1, 4.0);
        self.wb.sheet_mut(self.sheet_idx).freeze = v.freeze;
        self.wb.sheet_mut(self.sheet_idx).freeze_dirty = true;
        self.sel = v.sel;
        self.sel_end = v.sel;
        self.view_active = Some(idx);
        self.ensure_visible();
        self.status = format!("已切换到工作表视图「{}」", v.name);
    }

    fn view_new_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut name) = self.view_new.clone() else { return };
        let mut open = true;
        let mut ok = false;
        ui_kit::window(ctx, "新建工作表视图", 360.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                ui_kit::field(ui, "名称", |ui| {
                    ui.add(
                        egui::TextEdit::singleline(&mut name)
                            .desired_width(220.0)
                            .hint_text("例如：看一季度"),
                    );
                });
                ui.label(
                    egui::RichText::new("保存当前缩放、冻结窗格和选区；视图存在本机（不进 xlsx）")
                        .size(10.5)
                        .weak(),
                );
                ui_kit::footer(ui, |ui| {
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        open = false;
                    }
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        ok = true;
                    }
                });
            });
        if ok && !name.trim().is_empty() {
            let v = self.view_capture(name.trim());
            // 同名覆盖
            if let Some(i) = self.views.iter().position(|x| x.name == v.name) {
                self.views[i] = v;
                self.view_active = Some(i);
            } else {
                self.views.push(v);
                self.view_active = Some(self.views.len() - 1);
            }
            ui_prefs::save_views(&self.views_key(), &self.views);
            self.status = format!("已保存工作表视图「{}」", name.trim());
            self.view_new = None;
            return;
        }
        self.view_new = if open { Some(name) } else { None };
    }

    fn views_window(&mut self, ctx: &egui::Context) {
        if !self.views_open {
            return;
        }
        let mut open = true;
        let mut pick: Option<usize> = None;
        let mut del: Option<usize> = None;
        let views = self.views.clone();
        let active = self.view_active;
        ui_kit::window(ctx, "工作表视图", 420.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                if views.is_empty() {
                    ui.label("还没有保存的视图：用「视图 → 新建」把当前缩放/冻结/选区存下来。");
                }
                for (i, v) in views.iter().enumerate() {
                    ui.horizontal(|ui| {
                        let mark = if active == Some(i) { "● " } else { "　" };
                        if ui
                            .selectable_label(active == Some(i), format!("{mark}{}", v.name))
                            .clicked()
                        {
                            pick = Some(i);
                        }
                        ui.label(
                            egui::RichText::new(format!(
                                "{} 表 · {:.0}% · {}",
                                v.sheet + 1,
                                v.zoom * 100.0,
                                v.freeze
                                    .map(|(r, c)| format!("冻结 {r} 行 {c} 列"))
                                    .unwrap_or_else(|| "无冻结".into())
                            ))
                            .size(10.5)
                            .weak(),
                        );
                        if ui.small_button("删除").clicked() {
                            del = Some(i);
                        }
                    });
                }
            });
        if let Some(i) = pick {
            self.view_apply(i);
        }
        if let Some(i) = del {
            self.views.remove(i);
            self.view_active = None;
            ui_prefs::save_views(&self.views_key(), &self.views);
            self.status = "已删除视图".into();
        }
        self.views_open = open;
    }

    /// 取消隐藏：列出所有隐藏的表
    fn unhide_window(&mut self, ctx: &egui::Context) {
        if !self.unhide_open {
            return;
        }
        let mut open = true;
        let mut show_idx: Option<usize> = None;
        let hidden: Vec<(usize, String)> = self
            .wb
            .sheets
            .iter()
            .enumerate()
            .filter(|(_, s)| s.hidden && !s.very_hidden)
            .map(|(i, s)| (i, s.name.clone()))
            .collect();
        ui_kit::window(ctx, "取消隐藏", 340.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                if hidden.is_empty() {
                    ui.label("当前工作簿没有可取消隐藏的工作表。");
                }
                for (i, name) in &hidden {
                    if ui.selectable_label(false, name).clicked() {
                        show_idx = Some(*i);
                    }
                }
                ui.label(
                    egui::RichText::new("选中一张表即可恢复显示（深度隐藏表需在保护/属性中解除）")
                        .size(10.5)
                        .weak(),
                );
            });
        if let Some(i) = show_idx {
            if self.wb.protection.as_ref().is_some_and(|p| p.lock_structure) {
                self.status = "工作簿结构已受保护，无法取消隐藏工作表".into();
                self.unhide_open = false;
                return;
            }
            let sh = self.wb.sheet_mut(i);
            sh.set_visibility(sheetcore::model::SheetVisibility::Visible);
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.status = format!("已取消隐藏「{}」", self.wb.sheet(i).name);
            self.unhide_open = false;
            return;
        }
        self.unhide_open = open;
    }

    /// UI-16：把工作表移到指定插入位置（0..=len，len 为末尾），可 Ctrl+Z 撤销。
    fn move_sheet_to(&mut self, from: usize, target: usize) -> bool {
        let len = self.wb.sheets.len();
        if from >= len || target > len || from == target || from + 1 == target {
            return false;
        }
        if !self.can_change_sheets() {
            return false;
        }
        let active_id = self.wb.sheet(self.sheet_idx).identity;
        let prev_focus = (self.sheet_idx, self.sel.0, self.sel.1);
        let mut dest = if target > from { target - 1 } else { target };
        dest = dest.min(len - 1);
        if dest == from {
            return false;
        }
        if !self.undo.move_sheet(&mut self.wb, from, dest, prev_focus) {
            return false;
        }
        if let Some(new_idx) = self.wb.sheets.iter().position(|s| s.identity == active_id) {
            self.sheet_idx = new_idx;
        }
        self.selected_sheets.clear();
        self.refresh_after_sheet_change();
        self.status = format!(
            "已移动「{}」到第 {} 位（可 Ctrl+Z 撤销）",
            self.wb.sheet(dest).name,
            dest + 1
        );
        true
    }

    /// UI-16：复制工作表到指定插入位置（0..=len，len 为末尾），可 Ctrl+Z 撤销。
    fn copy_sheet_to(&mut self, from: usize, target: usize) -> bool {
        let len = self.wb.sheets.len();
        if from >= len {
            return false;
        }
        if !self.can_change_sheets() {
            return false;
        }
        let prev_focus = (self.sheet_idx, self.sel.0, self.sel.1);
        let active_id = self.wb.sheet(self.sheet_idx).identity;
        self.remember_sheet_view();
        let mut copy = self.wb.sheets[from].clone();
        let base = copy.name.clone();
        let mut n = 2;
        let suffix = format!(" ({n})");
        let mut name = format!(
            "{}{suffix}",
            base.chars().take(31usize.saturating_sub(suffix.chars().count())).collect::<String>()
        );
        while self.wb.sheets.iter().any(|s| s.name.eq_ignore_ascii_case(&name)) {
            n += 1;
            let suffix = format!(" ({n})");
            name = format!(
                "{}{suffix}",
                base.chars().take(31usize.saturating_sub(suffix.chars().count())).collect::<String>()
            );
        }
        copy.name = name.clone();
        Self::prepare_cloned_sheet_objects(&self.wb, &mut copy, &base);
        copy.hidden = false;
        copy.very_hidden = false;
        let at = target.min(self.wb.sheets.len());
        if !sheetcore::sheet_ops::insert_sheet(&mut self.wb, at, copy) {
            self.status = "复制工作表失败：名称无效或已存在".into();
            return false;
        }
        self.undo.record_inserted_sheet(&self.wb, at, "复制工作表", prev_focus);
        self.sheet_idx = self
            .wb
            .sheets
            .iter()
            .position(|s| s.identity == active_id)
            .unwrap_or(at);
        self.switch_sheet_view(at);
        self.selected_sheets.clear();
        self.refresh_after_sheet_change();
        self.status = format!("已复制为「{name}」（可 Ctrl+Z 撤销）");
        true
    }

    /// 跨工作簿移动或复制工作表（目标可为另一个已打开标签或新建工作簿；完整重映射样式并克隆图表/表格）
    fn transfer_sheet_to_workbook(
        &mut self,
        from: usize,
        target_doc: usize,
        copy: bool,
    ) -> bool {
        if from >= self.wb.sheets.len() {
            return false;
        }
        if !copy {
            if self.wb.sheets.len() <= 1 {
                self.status = "无法移出最后一张工作表（至少保留一张，或勾选「建立副本」）".into();
                return false;
            }
            if !self.can_change_sheets() {
                return false;
            }
        }
        let src_sheet = self.wb.sheets[from].clone();
        let src_styles = self.wb.styles.clone();
        let orig_name = src_sheet.name.clone();
        let clone_into = |dst_wb: &mut Workbook| -> String {
            let mut sh = src_sheet.clone();
            let mut style_map: HashMap<u16, u16> = HashMap::new();
            let mut map_sid = |styles: &mut sheetcore::style::StyleTable, sid: u16| -> u16 {
                if sid == 0 {
                    return 0;
                }
                *style_map
                    .entry(sid)
                    .or_insert_with(|| styles.copy_from(&src_styles, sid))
            };
            let cell_styles: Vec<(sheetcore::CellRef, u16)> = sh
                .styles
                .iter()
                .map(|(k, &sid)| (k, map_sid(&mut dst_wb.styles, sid)))
                .collect();
            sh.styles = Default::default();
            for (k, sid) in cell_styles {
                if sid != 0 {
                    sh.styles.insert(k, sid);
                }
            }
            let row_st: Vec<(u32, u16)> = sh
                .row_styles
                .iter()
                .map(|(&r, &sid)| (r, map_sid(&mut dst_wb.styles, sid)))
                .collect();
            sh.row_styles.clear();
            for (r, sid) in row_st {
                if sid != 0 {
                    sh.row_styles.insert(r, sid);
                }
            }
            let col_st: Vec<(u32, u16)> = sh
                .col_styles
                .iter()
                .map(|(&c, &sid)| (c, map_sid(&mut dst_wb.styles, sid)))
                .collect();
            sh.col_styles.clear();
            for (c, sid) in col_st {
                if sid != 0 {
                    sh.col_styles.insert(c, sid);
                }
            }
            let mut name = orig_name.clone();
            let mut n = 2usize;
            while dst_wb.sheets.iter().any(|s| s.name.eq_ignore_ascii_case(&name)) {
                let suffix = format!(" ({n})");
                name = format!(
                    "{}{suffix}",
                    orig_name
                        .chars()
                        .take(31usize.saturating_sub(suffix.chars().count()))
                        .collect::<String>()
                );
                n += 1;
            }
            sh.name = name.clone();
            Self::prepare_cloned_sheet_objects(dst_wb, &mut sh, &orig_name);
            sh.hidden = false;
            sh.very_hidden = false;
            let idx = dst_wb.sheets.len();
            sheetcore::sheet_ops::insert_sheet(dst_wb, idx, sh);
            name
        };

        if target_doc == usize::MAX {
            // 移入新工作簿
            let mut new_wb = Workbook::new_blank();
            new_wb.sheets.clear();
            let placed = clone_into(&mut new_wb);
            new_wb.dirty = true;
            if !copy {
                self.delete_sheet(from);
            }
            self.release_lock();
            self.cancel_bg_recalc_on_switch();
            let parked = self.park_current();
            self.tabs[self.active_tab] = TabSlot::Parked(parked);
            self.tabs.push(TabSlot::Active);
            self.active_tab = self.tabs.len() - 1;
            self.reset_editor_state();
            self.wb = new_wb;
            self.doc_uid = next_doc_uid();
            self.wb_epoch = self.wb_epoch.wrapping_add(1);
            self.load_sheet_view(0);
            self.recalc_all_and_deps_adaptive();
            self.status = format!("已将「{placed}」{}到新工作簿", if copy { "复制" } else { "移动" });
            return true;
        }
        if target_doc >= self.tabs.len() || target_doc == self.active_tab {
            return false;
        }
        if let TabSlot::Parked(doc) = &mut self.tabs[target_doc] {
            if doc.wb.protection.as_ref().is_some_and(|p| p.lock_structure) {
                self.status = format!("目标工作簿「{}」结构已受保护，无法写入工作表", doc.title);
                return false;
            }
            let placed = clone_into(&mut doc.wb);
            doc.wb.dirty = true;
            doc.deps_built = false;
            doc.doc_gen = doc.doc_gen.wrapping_add(1);
            let dst_title = doc.title.clone();
            if !copy {
                self.delete_sheet(from);
            }
            self.status = format!(
                "已将「{placed}」{}到「{dst_title}」",
                if copy { "复制" } else { "移动" }
            );
            return true;
        }
        false
    }

    /// UI-16：移动或复制工作表的对话框（支持当前工作簿、其他已打开工作簿及新工作簿）。
    fn sheet_move_window(&mut self, ctx: &egui::Context) {
        let Some(mut d) = self.sheet_move_dlg else {
            return;
        };
        let len = self.wb.sheets.len();
        let src_name = self.wb.sheets.get(d.src).map(|s| s.name.clone()).unwrap_or_default();
        let names: Vec<String> = self.wb.sheets.iter().map(|s| s.name.clone()).collect();
        let mut doc_choices: Vec<(Option<usize>, String)> = vec![(None, format!("当前工作簿 ({})", self.wb.title()))];
        for (ti, slot) in self.tabs.iter().enumerate() {
            if ti != self.active_tab {
                if let TabSlot::Parked(p) = slot {
                    doc_choices.push((Some(ti), p.title.clone()));
                }
            }
        }
        doc_choices.push((Some(usize::MAX), "(新工作簿)".to_string()));
        let mut open = true;
        let mut apply = false;
        ui_kit::window(ctx, "移动或复制工作表", 420.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                ui.label(format!("源工作表：{}", src_name));
                ui.checkbox(&mut d.copy, "建立副本");
                ui.horizontal(|ui| {
                    ui.label("工作簿");
                    let cur_doc_label = doc_choices
                        .iter()
                        .find(|(k, _)| *k == d.target_doc)
                        .map(|(_, l)| l.clone())
                        .unwrap_or_else(|| "当前工作簿".into());
                    egui::ComboBox::from_id_salt("sheet_move_target_doc")
                        .selected_text(cur_doc_label)
                        .width(240.0)
                        .show_ui(ui, |ui| {
                            for (k, label) in &doc_choices {
                                ui.selectable_value(&mut d.target_doc, *k, label);
                            }
                        });
                });
                if d.target_doc.is_none() {
                    ui.horizontal(|ui| {
                        ui.label("位置");
                        let selected = if d.target >= len {
                            "移到末尾".to_string()
                        } else {
                            format!("移到「{}」之前", names.get(d.target).cloned().unwrap_or_default())
                        };
                        egui::ComboBox::from_id_salt("sheet_move_target")
                            .selected_text(selected)
                            .width(240.0)
                            .show_ui(ui, |ui| {
                                for i in 0..=len {
                                    let label = if i == len {
                                        "移到末尾".to_string()
                                    } else {
                                        format!("移到「{}」之前", names.get(i).cloned().unwrap_or_default())
                                    };
                                    ui.selectable_value(&mut d.target, i, label);
                                }
                            });
                    });
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::primary_button(ui, "确定").clicked() {
                        apply = true;
                    }
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        open = false;
                    }
                });
            });
        if apply {
            let ok = if let Some(tdoc) = d.target_doc {
                self.transfer_sheet_to_workbook(d.src, tdoc, d.copy)
            } else if d.copy {
                self.copy_sheet_to(d.src, d.target)
            } else {
                self.move_sheet_to(d.src, d.target)
            };
            self.sheet_move_dlg = if open && !ok { Some(d) } else { None };
            return;
        }
        self.sheet_move_dlg = if open { Some(d) } else { None };
    }

    /// UI-16：工作表列表的搜索过滤（隐藏表不参与）。
    fn sheet_list_matches(&self, query: &str) -> Vec<usize> {
        let q = query.trim().to_lowercase();
        self.wb
            .sheets
            .iter()
            .enumerate()
            .filter(|(_, s)| !s.hidden)
            .filter(|(_, s)| q.is_empty() || s.name.to_lowercase().contains(&q))
            .map(|(i, _)| i)
            .collect()
    }

    /// UI-16：工作表列表，带搜索定位；大量工作表时不用横向找标签。
    fn sheet_list_window(&mut self, ctx: &egui::Context) {
        if !self.sheet_list_open {
            return;
        }
        let mut open = true;
        let mut query = self.sheet_list_query.clone();
        let mut pick: Option<usize> = None;
        let sheets: Vec<(usize, String, bool)> = self
            .wb
            .sheets
            .iter()
            .enumerate()
            .map(|(i, s)| (i, s.name.clone(), s.hidden))
            .collect();
        ui_kit::window(ctx, "工作表列表", 360.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    ui.label("搜索");
                    ui.add(
                        egui::TextEdit::singleline(&mut query)
                            .desired_width(240.0)
                            .hint_text("输入表名"),
                    );
                });
                ui.separator();
                egui::ScrollArea::vertical().max_height(360.0).show(ui, |ui| {
                    let matches = self.sheet_list_matches(&query);
                    let mut shown = 0usize;
                    for (i, name, hidden) in &sheets {
                        if *hidden || !matches.contains(i) {
                            continue;
                        }
                        shown += 1;
                        let label = if *i == self.sheet_idx {
                            format!("● {name}")
                        } else {
                            format!("　{name}")
                        };
                        if ui.selectable_label(*i == self.sheet_idx, label).clicked() {
                            pick = Some(*i);
                        }
                    }
                    if shown == 0 {
                        ui.weak("没有匹配的工作表");
                    }
                });
            });
        self.sheet_list_query = query;
        if let Some(i) = pick {
            if self.switch_sheet_view(i) {
                self.status = format!("当前工作表：{}", self.wb.sheet(self.sheet_idx).name);
                open = false;
            }
        }
        self.sheet_list_open = open;
    }

    /// 隐藏当前工作表（至少留一张可见）
    fn hide_current_sheet(&mut self) {
        if !self.can_change_sheets() {
            return;
        }
        // 隐藏会切表，必须先提交正在编辑的内容；验证拒绝时保留原表、编辑文本、选区。
        if !self.finish_pending_edit() {
            return;
        }
        let visible = self.wb.sheets.iter().filter(|s| !s.is_hidden()).count();
        if visible <= 1 {
            self.status = "至少要留一张可见的工作表".into();
            return;
        }
        let i = self.sheet_idx;
        let name = self.wb.sheet(i).name.clone();
        self.remember_sheet_view();
        let sh = self.wb.sheet_mut(i);
        sh.set_visibility(sheetcore::model::SheetVisibility::Hidden);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        if let Some(net) = self.net.as_ref() {
            net.broadcast_sheet_meta(
                i,
                sheetcore::sync::SheetMetaKind::SheetTab(
                    sheetcore::sync::SheetTabSync::Visibility {
                        name: name.clone(),
                        hidden: true,
                        very_hidden: false,
                    },
                ),
            );
        }
        // 切到下一张可见表，走统一入口（提交/清格式刷/加载视图）。
        if let Some(next) = self
            .wb
            .sheets
            .iter()
            .enumerate()
            .position(|(k, s)| k != i && !s.is_hidden())
        {
            let _ = self.switch_sheet_view(next);
        }
        self.status = format!("已隐藏「{name}」；视图 → 取消隐藏 可以恢复");
    }

    // ---------------------------------------------------------------- 辅助功能 / 批注导航

    fn a11y_scan(&mut self) {
        self.a11y_list = sheetcore::a11y::scan(&self.wb);
        self.status = format!("辅助功能检查器：{} 项", self.a11y_list.len());
    }

    fn a11y_window(&mut self, ctx: &egui::Context) {
        if !self.a11y_open {
            return;
        }
        let mut open = true;
        let mut jump: Option<(usize, (u32, u32))> = None;
        let mut rescan = false;
        let list = self.a11y_list.clone();
        ui_kit::window(ctx, "辅助功能检查器", 560.0)
            .open(&mut open)
            .resizable(true)
            .default_size([560.0, 380.0])
            .show(ctx, |ui| {
                ui.horizontal(|ui| {
                    let n = list.len();
                    let (text, color) = if n == 0 {
                        ("一切就绪：没有发现辅助功能问题".to_string(), ui_kit::ACCENT)
                    } else {
                        (format!("发现 {n} 项需要处理"), Color32::from_rgb(192, 0, 0))
                    };
                    ui.label(egui::RichText::new(text).size(12.5).color(color));
                    if ui_kit::secondary_button(ui, "重新检查").clicked() {
                        rescan = true;
                    }
                });
                ui.separator();
                egui::ScrollArea::vertical().max_height(300.0).show(ui, |ui| {
                    egui::Grid::new("a11y_grid")
                        .num_columns(4)
                        .spacing([10.0, 4.0])
                        .striped(true)
                        .show(ui, |ui| {
                            ui.label(egui::RichText::new("工作表").size(11.0).weak());
                            ui.label(egui::RichText::new("位置").size(11.0).weak());
                            ui.label(egui::RichText::new("问题").size(11.0).weak());
                            ui.label(egui::RichText::new("建议").size(11.0).weak());
                            ui.end_row();
                            for it in &list {
                                ui.label(egui::RichText::new(&it.sheet_name).size(11.0));
                                match it.at {
                                    Some((r, c)) => {
                                        if ui.link(cell_name(r, c)).clicked() {
                                            jump = Some((it.sheet, (r, c)));
                                        }
                                    }
                                    None => {
                                        ui.label("—");
                                    }
                                }
                                ui.label(
                                    egui::RichText::new(format!(
                                        "{}：{}",
                                        it.kind.label(),
                                        it.detail
                                    ))
                                    .size(11.0),
                                );
                                ui.label(egui::RichText::new(it.kind.advice()).size(10.5).weak());
                                ui.end_row();
                            }
                        });
                });
            });
        if rescan {
            self.a11y_scan();
        }
        if let Some((si, (r, c))) = jump {
            let target = si.min(self.wb.sheets.len() - 1);
            if target != self.sheet_idx && !self.switch_sheet_view(target) {
                self.a11y_open = open;
                return;
            }
            self.sel = (r, c);
            self.sel_end = (r, c);
            self.ensure_visible();
        }
        self.a11y_open = open;
    }

    fn broadcast_note_meta(
        &self,
        sheet: usize,
        r: u32,
        c: u32,
        note: Option<&sheetcore::notes::Note>,
    ) -> bool {
        let Some(net) = self.net.as_ref() else { return true };
        let kind = match note {
            Some(n) => sheetcore::sync::SheetMetaKind::Note {
                row: r,
                col: c,
                author: n.author.clone(),
                text: Some(n.text.clone()),
            },
            None => sheetcore::sync::SheetMetaKind::Note {
                row: r,
                col: c,
                author: String::new(),
                text: None,
            },
        };
        net.broadcast_sheet_meta(sheet, kind)
    }

