    pub(crate) fn broadcast_note_undo_edit(&self, edit: &sheetcore::undo::NoteUndoEdit) {
        let Some(net) = self.net.as_ref() else { return };
        for (sheet, kind) in edit.to_meta_sync(true) {
            net.broadcast_sheet_meta(sheet, kind);
        }
    }

    /// 统一的删除/清除选区批注与线程会话入口（右键「删除批注」与功能区「清除批注」共用）
    pub(crate) fn delete_comments_in_selection(&mut self, label: &str) {
        if self.edit_blocked() {
            return;
        }
        let targets = self.comment_keys_in_sel();
        if targets.is_empty() {
            self.status = "所选区域没有批注".into();
            return;
        }
        if !self.thread_change_allowed(targets.iter().any(|key| self.wb.sheet(self.sheet_idx).threads.contains_key(key))) { return; }
        let gate: Vec<(u32, u32)> = targets.iter().map(|k| (k.row, k.col)).collect();
        if !self.write_preflight(&gate, label) {
            return;
        }
        let si = self.sheet_idx;
        let sheet_id = self.wb.sheet(si).identity;
        let mut note_diffs = Vec::new();
        let mut thread_diffs = Vec::new();
        {
            let sh = self.wb.sheet_mut(si);
            for k in &targets {
                if let Some(old) = sh.notes.remove(k) {
                    note_diffs.push(((k.row, k.col), Some(old), None));
                }
                if let Some(old_tc) = sh.threads.remove(k) {
                    thread_diffs.push(((k.row, k.col), Some(old_tc), None));
                }
                self.pinned_comments.remove(&(sheet_id, *k));
                self.comment_card_offsets.remove(&(sheet_id, *k));
            }
            if !note_diffs.is_empty() {
                sh.notes_dirty = true;
            }
            if !thread_diffs.is_empty() {
                sh.threads_dirty = true;
            }
            if !note_diffs.is_empty() || !thread_diffs.is_empty() {
                sh.bump_display_style_revision();
            }
        }
        let removed_cells: std::collections::HashSet<(u32, u32)> = note_diffs
            .iter()
            .map(|(p, ..)| *p)
            .chain(thread_diffs.iter().map(|(p, ..)| *p))
            .collect();
        let removed = removed_cells.len();
        if removed > 0 {
            self.broadcast_comment_diffs(si, &note_diffs, &thread_diffs);
            self.undo.push_meta(
                label,
                (si, self.sel.0, self.sel.1),
                sheetcore::undo::MetaEdit {
                    sheet: si,
                    notes: note_diffs,
                    threads: thread_diffs,
                    ..Default::default()
                },
            );
            self.wb.dirty = true;
            self.doc_gen = self.doc_gen.wrapping_add(1);
            self.tasks.last_edit = Some(std::time::Instant::now());
            self.status = if removed == 1 {
                format!("已{label}")
            } else {
                format!("已{label} {removed} 条")
            };
        } else {
            self.status = "所选区域没有批注".into();
        }
    }

    /// 合并单元格内部任意坐标统一归一化到左上角锚点（绘制与保存批注均挂在锚点上）
    pub(crate) fn note_anchor(&self, r: u32, c: u32) -> (u32, u32) {
        self.wb
            .sheet(self.sheet_idx)
            .merge_at(r, c)
            .map(|(mr1, mc1, _, _)| (mr1, mc1))
            .unwrap_or((r, c))
    }

    /// 收集当前选区（含交集的合并区域锚点）内所有批注与线程会话坐标
    pub(crate) fn comment_keys_in_sel(&self) -> Vec<sheetcore::model::CellRef> {
        let rects = self.sel_rects();
        let sh = self.wb.sheet(self.sheet_idx);
        let mut out: Vec<sheetcore::model::CellRef> = sh
            .notes
            .keys()
            .chain(sh.threads.keys())
            .copied()
            .filter(|k| {
                if rects
                    .iter()
                    .any(|&(r1, c1, r2, c2)| k.row >= r1 && k.row <= r2 && k.col >= c1 && k.col <= c2)
                {
                    return true;
                }
                if let Some((mr1, mc1, mr2, mc2)) = sh.merge_at(k.row, k.col) {
                    if (k.row, k.col) == (mr1, mc1) {
                        return rects
                            .iter()
                            .any(|&(r1, c1, r2, c2)| mr1 <= r2 && mr2 >= r1 && mc1 <= c2 && mc2 >= c1);
                    }
                }
                false
            })
            .collect();
        out.sort_by_key(|k| (k.row, k.col));
        out.dedup();
        out
    }

    pub(crate) fn selection_has_comment(&self) -> bool {
        !self.comment_keys_in_sel().is_empty()
    }

    pub(crate) fn merge_at_fast(&self, r: u32, c: u32) -> Option<(u32, u32, u32, u32)> {
        let sh = self.wb.sheet(self.sheet_idx);
        if sh.merges.is_empty() {
            return None;
        }
        if self.cf_inputs.merges.matches(sh) {
            self.cf_inputs.merges.at(r, c)
        } else {
            sh.merge_at(r, c)
        }
    }

    pub(crate) fn selection_has_merge(&self) -> bool {
        let sh = self.wb.sheet(self.sheet_idx);
        if sh.merges.is_empty() {
            return false;
        }
        let rects = self.sel_rects();
        if self.cf_inputs.merges.matches(sh) {
            return rects
                .iter()
                .any(|&(sr1, sc1, sr2, sc2)| self.cf_inputs.merges.has_overlap(sr1, sc1, sr2, sc2));
        }
        sh.merges.iter().any(|&(mr1, mc1, mr2, mc2)| {
            rects
                .iter()
                .any(|&(sr1, sc1, sr2, sc2)| mr1 <= sr2 && mr2 >= sr1 && mc1 <= sc2 && mc2 >= sc1)
        })
    }

    pub(crate) fn can_merge_selection(&self) -> bool {
        let (r1, c1, r2, c2) = self.sel_rect();
        if r1 == r2 && c1 == c2 {
            return false;
        }
        self.merge_at_fast(r1, c1) != Some((r1, c1, r2, c2))
    }

    /// 当前工作表内所有批注/线程会话的排序坐标列表
    pub(crate) fn sheet_comment_keys(&self, sheet_idx: usize) -> Vec<(u32, u32)> {
        let Some(sh) = self.wb.sheets.get(sheet_idx) else {
            return Vec::new();
        };
        let mut keys: Vec<(u32, u32)> = sh
            .notes
            .keys()
            .chain(sh.threads.keys())
            .map(|k| (k.row, k.col))
            .collect();
        keys.sort_unstable();
        keys.dedup();
        keys
    }

    /// 切换指定单元格批注的单格固定常显状态
    pub(crate) fn toggle_pin_comment(&mut self, sheet_idx: usize, r: u32, c: u32) -> bool {
        let Some(sh) = self.wb.sheets.get(sheet_idx) else {
            return false;
        };
        let (ar, ac) = sh.merge_at(r, c).map(|(mr1, mc1, _, _)| (mr1, mc1)).unwrap_or((r, c));
        let key = sheetcore::model::CellRef::new(ar, ac);
        if !sh.notes.contains_key(&key) && !sh.threads.contains_key(&key) {
            return false;
        }
        let sid = sh.identity;
        if self.pinned_comments.remove(&(sid, key)) {
            self.status = format!("已隐藏固定批注 {}", cell_name(ar, ac));
            false
        } else {
            self.pinned_comments.insert((sid, key));
            self.status = format!("已固定显示批注 {}", cell_name(ar, ac));
            true
        }
    }

    /// 统一打开批注编辑窗口（右键菜单、功能区、顶栏按钮、交互浮签共用）：
    /// 提交挂起格内编辑 -> 合并锚点归一化 -> 锁与保护门禁 -> 锚定到目标格旁自动聚焦 + 请求立即重绘。
    pub(crate) fn open_note_editor(&mut self, ctx: Option<&egui::Context>) {
        let anchor = self.last_sel_cell_rect.map(|rect| rect.right_top());
        self.open_note_editor_at(ctx, anchor);
    }

    pub(crate) fn open_note_editor_at(&mut self, ctx: Option<&egui::Context>, anchor: Option<egui::Pos2>) {
        if self.edit_blocked() {
            return;
        }
        if self.editing.is_some() && !self.finish_pending_edit() {
            return;
        }
        let (r, c) = self.note_anchor(self.sel.0, self.sel.1);
        if !self.write_preflight(&[(r, c)], "编辑批注") {
            return;
        }
        let key = sheetcore::model::CellRef::new(r, c);
        let sh = self.wb.sheet(self.sheet_idx);
        let cur = sh
            .threads
            .get(&key)
            .and_then(|tc| tc.entries.first().map(|e| e.text.clone()))
            .or_else(|| sh.notes.get(&key).map(|n| n.text.clone()))
            .unwrap_or_default();
        self.note_edit = Some((r, c, cur));
        self.note_edit_sheet = self.sheet_idx;
        self.note_edit_anchor = anchor;
        self.note_reply_buf.clear();
        self.note_focus_requested = true;
        if let Some(ctx) = ctx {
            ctx.request_repaint();
        }
    }

    /// 上一条/下一条批注：按行列排序在当前表里找（涵盖传统批注与线程批注）
    fn note_step(&mut self, forward: bool) {
        let keys = self.sheet_comment_keys(self.sheet_idx);
        if keys.is_empty() {
            self.status = "当前表没有批注".into();
            return;
        }
        let cur = self.note_anchor(self.sel.0, self.sel.1);
        let target = if forward {
            keys.iter()
                .find(|k| **k > cur)
                .copied()
                .unwrap_or(keys[0])
        } else {
            keys.iter()
                .rev()
                .find(|k| **k < cur)
                .copied()
                .unwrap_or(*keys.last().unwrap())
        };
        self.sel = target;
        self.sel_end = target;
        self.ensure_visible();
        self.status = format!("批注 {}", cell_name(target.0, target.1));
    }

    /// 显示/隐藏当前批注（Excel/WPS 原生语义）：
    /// - 当前格有批注：切换该格的单格固定常显状态；
    /// - 当前格无批注：跳到当前表第一条批注并固定显示。
    fn note_show(&mut self) {
        let si = self.sheet_idx;
        let (r, c) = self.note_anchor(self.sel.0, self.sel.1);
        let key = sheetcore::model::CellRef::new(r, c);
        let has_cur = {
            let sh = self.wb.sheet(si);
            sh.notes.contains_key(&key) || sh.threads.contains_key(&key)
        };
        if has_cur {
            if self.show_all_comments {
                self.show_all_comments = false;
                let sid = self.wb.sheet(si).identity;
                self.pinned_comments.remove(&(sid, key));
                self.status = format!("已关闭全部显示并隐藏批注 {}", cell_name(r, c));
            } else {
                self.toggle_pin_comment(si, r, c);
            }
        } else {
            let keys = self.sheet_comment_keys(si);
            if keys.is_empty() {
                self.status = "当前表没有批注".into();
                return;
            }
            let t = keys[0];
            self.sel = t;
            self.sel_end = t;
            self.ensure_visible();
            let sid = self.wb.sheet(si).identity;
            self.pinned_comments.insert((sid, sheetcore::model::CellRef::new(t.0, t.1)));
            self.status = format!("已定位并固定显示批注 {}", cell_name(t.0, t.1));
        }
    }

    // ---------------------------------------------------------------- 数据工具

    /// 预测工作表：Holt-Winters ETS（含自动季节性检测 + 置信上下界 + 日期时间轴外推）
    fn forecast_run(&mut self, range: &str, periods: u32) -> Result<String, String> {
        self.forecast_run_opts(range, periods, 0, 95)
    }

    fn forecast_run_opts(
        &mut self,
        range: &str,
        periods: u32,
        season_len: usize,
        confidence_pct: u8,
    ) -> Result<String, String> {
        let Some(raw_rect) = Self::parse_rect(range) else {
            return Err(format!("区域「{range}」看不懂，写成 A1:B13 或 A1:A13"));
        };
        let Some((r1, c1, r2, c2)) = self.clamp_rect_to_used(raw_rect) else {
            return Err("选区内没有数据".into());
        };
        // 若选区有 >=2 列且第一列是日期/递增序号轴，则第一列作时间轴、第二列作数值列；否则取第一个数值列
        let sh_src = self.wb.sheet(self.sheet_idx);
        let mut date_col: Option<u32> = None;
        let mut val_col: Option<u32> = None;
        let mut num_cols: Vec<u32> = Vec::new();
        for c in c1..=c2 {
            let n = (r1..=r2)
                .filter(|r| matches!(sh_src.value(*r, c), Value::Number(_)))
                .count();
            if n >= 2 {
                num_cols.push(c);
            }
        }
        if num_cols.len() >= 2 {
            let c0 = num_cols[0];
            let looks_date = (r1..=r2).any(|r| {
                matches!(sh_src.value(r, c0), Value::Number(_))
                    && sheetcore::style::is_date_format(&self.wb.styles.get(sh_src.style_of(r, c0)).format)
            });
            if looks_date {
                date_col = Some(c0);
                val_col = Some(num_cols[1]);
            } else {
                date_col = Some(c0);
                val_col = Some(num_cols[1]);
            }
        } else if let Some(&c) = num_cols.first() {
            val_col = Some(c);
        }
        let Some(vc) = val_col else {
            return Err("选区内没有至少两个数字的列".into());
        };
        let mut xs: Vec<f64> = Vec::new();
        let mut ys: Vec<f64> = Vec::new();
        let mut date_fmt: Option<String> = None;
        for r in r1..=r2 {
            if let Value::Number(y) = sh_src.value(r, vc) {
                let x = if let Some(dc) = date_col {
                    if date_fmt.is_none() {
                        let f = &self.wb.styles.get(sh_src.style_of(r, dc)).format;
                        if sheetcore::style::is_date_format(f) {
                            date_fmt = Some(f.clone());
                        }
                    }
                    match sh_src.value(r, dc) {
                        Value::Number(xv) => xv,
                        _ => xs.len() as f64 + 1.0,
                    }
                } else {
                    xs.len() as f64 + 1.0
                };
                xs.push(x);
                ys.push(y);
            }
        }
        let conf = (confidence_pct.clamp(50, 99) as f64) / 100.0;
        let forced_season = (season_len >= 2).then_some(season_len);
        let Some(ets) = sheetcore::forecast::ets(&ys, periods as usize, forced_season, conf) else {
            return Err("数据太少，至少需要 2 个数值点才能预测".into());
        };
        let x_step = if xs.len() >= 2 {
            let mut diffs: Vec<f64> = xs.windows(2).map(|w| w[1] - w[0]).filter(|d| d.is_finite() && *d > 0.0).collect();
            diffs.sort_by(|a, b| a.total_cmp(b));
            diffs.get(diffs.len() / 2).copied().unwrap_or(1.0)
        } else {
            1.0
        };
        let last_x = xs.last().copied().unwrap_or(0.0);

        // 新建工作表
        let mut name = "预测".to_string();
        let mut k = 2;
        while self.wb.sheets.iter().any(|s| s.name == name) {
            name = format!("预测{k}");
            k += 1;
        }
        let mut sh = sheetcore::Sheet::new(name.clone());
        let date_sid = date_fmt.as_ref().map(|fmt| {
            let mut st = sheetcore::style::CellStyle::default();
            st.format = fmt.clone();
            self.wb.styles.intern(st)
        });
        let pct_lbl = confidence_pct.clamp(50, 99);
        sh.set(0, 0, Cell { value: Value::Text(if date_fmt.is_some() { "时间" } else { "期" }.into()), formula: None });
        sh.set(0, 1, Cell { value: Value::Text("原值".into()), formula: None });
        sh.set(0, 2, Cell { value: Value::Text("ETS拟合值".into()), formula: None });
        sh.set(0, 3, Cell { value: Value::Text("预测值".into()), formula: None });
        sh.set(0, 4, Cell { value: Value::Text(format!("{pct_lbl}%置信下界").into()), formula: None });
        sh.set(0, 5, Cell { value: Value::Text(format!("{pct_lbl}%置信上界").into()), formula: None });
        for i in 0..ys.len() {
            let r = i as u32 + 1;
            sh.set(r, 0, Cell { value: Value::Number(xs[i]), formula: None });
            if let Some(sid) = date_sid {
                sh.set_style(r, 0, sid);
            }
            sh.set(r, 1, Cell { value: Value::Number(ys[i]), formula: None });
            sh.set(r, 2, Cell { value: Value::Number(ets.fitted[i]), formula: None });
        }
        let n = ys.len() as u32;
        for k in 0..ets.future.len() {
            let r = n + 1 + k as u32;
            sh.set(r, 0, Cell { value: Value::Number(last_x + x_step * (k as f64 + 1.0)), formula: None });
            if let Some(sid) = date_sid {
                sh.set_style(r, 0, sid);
            }
            sh.set(r, 3, Cell { value: Value::Number(ets.future[k]), formula: None });
            sh.set(r, 4, Cell { value: Value::Number(ets.lower[k]), formula: None });
            sh.set(r, 5, Cell { value: Value::Number(ets.upper[k]), formula: None });
        }
        let info = [
            ("水平平滑 α", ets.alpha),
            ("趋势平滑 β", ets.beta),
            ("季节平滑 γ", ets.gamma),
            ("季节周期", ets.season_len as f64),
            ("均方根误差 RMSE", ets.rmse),
            ("平均绝对误差 MAE", ets.mae),
            ("拟合优度 R²", ets.r2),
        ];
        sh.set(0, 7, Cell { value: Value::Text("ETS 模型参数".into()), formula: None });
        for (i, (k2, v)) in info.iter().enumerate() {
            let r = i as u32 + 1;
            sh.set(r, 7, Cell { value: Value::Text((*k2).into()), formula: None });
            sh.set(r, 8, Cell { value: Value::Number(*v), formula: None });
        }
        self.wb.sheets.push(sh);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        let idx = self.wb.sheets.len() - 1;
        self.switch_sheet_view(idx);
        self.sel = (0, 0);
        self.sel_end = (0, 0);
        self.status = format!(
            "已生成 ETS 预测表「{name}」：季节周期={}，RMSE={:.4}，R²={:.3}，外推 {} 期（{pct_lbl}% 置信区间）",
            ets.season_len,
            ets.rmse,
            ets.r2,
            periods
        );
        Ok(self.status.clone())
    }

    /// 分类汇总
    fn subtotal_run(
        &mut self,
        range: &str,
        key: &str,
        value_cols: &str,
        f: sheetcore::subtotal::SubFn,
    ) -> Result<String, String> {
        self.subtotal_run_opts(
            range,
            key,
            value_cols,
            f,
            sheetcore::subtotal::SubtotalOpts {
                replace_existing: false,
                page_break_between_groups: false,
                summary_below: true,
            },
        )
    }

    fn subtotal_run_opts(
        &mut self,
        range: &str,
        key: &str,
        value_cols: &str,
        f: sheetcore::subtotal::SubFn,
        opts: sheetcore::subtotal::SubtotalOpts,
    ) -> Result<String, String> {
        let Some(raw_rect) = Self::parse_rect(range) else {
            return Err(format!("区域「{range}」看不懂"));
        };
        let Some(rect) = self.clamp_rect_to_used(raw_rect) else {
            return Err("选区内没有可分组的行".into());
        };
        let key_col = Self::parse_col(key)
            .ok_or_else(|| format!("分组列「{key}」看不懂，写成 A 或 1"))?;
        let mut cols: Vec<u32> = Vec::new();
        for part in value_cols.split([',', '，']) {
            let p = part.trim();
            if p.is_empty() {
                continue;
            }
            let c = Self::parse_col(p).ok_or_else(|| format!("汇总列「{p}」看不懂"))?;
            cols.push(c);
        }
        if cols.is_empty() {
            return Err("至少填一个汇总列".into());
        }
        if self.net.is_some() {
            return Err("分类汇总会插入多行并更新全簿引用。请先断开协作再执行。".into());
        }
        if !self.write_preflight_op(&[], "分类汇总", sheetcore::protection::ProtOp::InsertRows) {
            return Err(self.status.clone());
        }
        let idx = self.sheet_idx;
        let earliest = sheetcore::structural::Structural::InsertRows { at: rect.0 + 1, n: 1 };
        let before = sheetcore::undo::snapshot_structure(&self.wb, idx, &earliest);
        let rep = sheetcore::subtotal::try_subtotal_workbook_opts(
            &mut self.wb,
            idx,
            rect,
            key_col,
            &cols,
            f,
            opts,
        )?;
        if rep.groups == 0 {
            return Err("选区内没有可分组的行".into());
        }
        sheetcore::formula::recalc_all(&mut self.wb);
        self.deps = sheetcore::formula::deps::Deps::build_after_recalc(&self.wb).into();
        self.deps_built = true;
        let after = before.capture_after(&self.wb);
        self.undo.push_structure("分类汇总", before, after, (idx, self.sel.0, self.sel.1));
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!("分类汇总：{} 组，插了 {} 行（{}）", rep.groups, rep.rows, f.label());
        Ok(self.status.clone())
    }

    /// 快速填充
    fn flashfill_run(
        &mut self,
        range: &str,
        src: &str,
        dst: &str,
        aux: &str,
    ) -> Result<String, String> {
        let Some(raw_rect) = Self::parse_rect(range) else {
            return Err(format!("区域「{range}」看不懂"));
        };
        let mut rect = raw_rect;
        if rect.2.saturating_sub(rect.0) > 200_000 {
            if let Some((_, _, ur2, _)) = self.wb.sheet(self.sheet_idx).used_bounds() {
                rect.2 = rect.2.min(ur2.max(rect.0));
            } else {
                return Err("选区内没有数据".into());
            }
        }
        if rect.2.saturating_sub(rect.0) > 200_000 {
            return Err("快速填充单次最多支持 20 万行，请缩小范围".into());
        }
        let src_col = Self::parse_col(src).ok_or_else(|| format!("源列「{src}」看不懂"))?;
        let dst_col = Self::parse_col(dst).ok_or_else(|| format!("目标列「{dst}」看不懂"))?;
        let aux_col = if aux.trim().is_empty() {
            None
        } else {
            Some(Self::parse_col(aux).ok_or_else(|| format!("辅助列「{aux}」看不懂"))?)
        };
        let keys: Vec<(u32, u32)> = (rect.0..=rect.2).map(|r| (r, dst_col)).collect();
        if !self.write_preflight(&keys, "快速填充") {
            return Err(self.status.clone());
        }
        let txn = self.txn_begin(&keys);
        let out = match sheetcore::flashfill::flash_fill(
            self.wb.sheet_mut(self.sheet_idx),
            src_col,
            dst_col,
            rect.0,
            rect.2,
            aux_col,
        ) {
            Ok(out) => out,
            Err(e) => {
                self.txn_end("快速填充", txn);
                return Err(e);
            }
        };
        self.txn_end("快速填充", txn);
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        let si = self.sheet_idx;
        let touched: Vec<(usize, u32, u32)> = keys.into_iter().map(|(r, c)| (si, r, c)).collect();
        self.recalc_and_broadcast(&touched);
        self.status = format!("规则快速填充：{}（填了 {} 格；按已识别规则，不是通用程序合成）", out.rule.label(), out.filled);
        Ok(self.status.clone())
    }

    /// Ctrl+E / Ribbon 快速填充一键触发：自动探测相邻列与连续数据区直接填充（含撤销、保护与重算）；
    /// 无示例或规律不明确时自动打开参数弹窗让用户指定源列/目标列。
    pub(crate) fn flash_fill_instant_or_dialog(&mut self) {
        if self.edit_blocked() {
            return;
        }
        self.commit_edit(None);
        let (r1, c1, mut r2, mut c2) = self.sel_rect();
        let si = self.sheet_idx;
        let dst_col = self.sel.1;
        let anchor_row = self.sel.0;
        let mut probe = self.wb.sheet(si).clone();
        if let Ok((preview, coords)) = sheetcore::flashfill::auto_flash_fill(&mut probe, dst_col, anchor_row) {
            if !coords.is_empty() {
                if !self.write_preflight(&coords, "快速填充") {
                    return;
                }
                let txn = self.txn_begin(&coords);
                if let Ok((out, written)) = sheetcore::flashfill::auto_flash_fill(self.wb.sheet_mut(si), dst_col, anchor_row) {
                    self.txn_end("快速填充", txn);
                    self.wb.dirty = true;
                    self.doc_gen = self.doc_gen.wrapping_add(1);
                    let touched: Vec<(usize, u32, u32)> = written.into_iter().map(|(r, c)| (si, r, c)).collect();
                    self.recalc_and_broadcast(&touched);
                    self.status = format!("快速填充完成：{}（填充 {} 格）", out.rule.label(), out.filled);
                    return;
                } else {
                    self.txn_end("快速填充", txn);
                }
            } else {
                let _ = preview;
                self.status = "目标列已全部填充，无需重复操作".into();
                return;
            }
        }
        if (r2 - r1 + 1) as u64 > 200_000 {
            if let Some((_, _, ur2, uc2)) = self.wb.sheet(si).used_bounds() {
                r2 = r2.min(ur2.max(r1));
                c2 = c2.min(uc2.max(c1));
            }
        }
        self.ff_dlg = Some(FlashDlg {
            range: format!("{}:{}", sheetcore::model::cell_name(r1, c1), sheetcore::model::cell_name(r2, c2)),
            src_col: sheetcore::model::col_label(c1.saturating_sub(if c1 == c2 && c1 > 0 { 1 } else { 0 })),
            dst_col: sheetcore::model::col_label(if c1 == c2 && c1 > 0 { c1 } else { c1 + 1 }),
            aux_col: if c2 > c1 + 1 { sheetcore::model::col_label(c2) } else { String::new() },
            msg: "未自动检测到相邻列示例，请确认源列与目标列后点击「填充」".into(),
        });
    }

    /// 合并计算
    fn consolidate_run(
        &mut self,
        sources: &str,
        f: sheetcore::consolidate::ConsFn,
        row_labels: bool,
        col_labels: bool,
    ) -> Result<String, String> {
        let mut list: Vec<sheetcore::consolidate::Source> = Vec::new();
        for line in sources.lines() {
            let line = line.trim();
            if line.is_empty() {
                continue;
            }
            let (sheet, rng) = match line.rsplit_once('!') {
                Some((s, r)) => {
                    let s = s.trim().trim_matches('\'').replace("''", "'");
                    (s, r.to_string())
                }
                None => (self.wb.sheet(self.sheet_idx).name.clone(), line.to_string()),
            };
            let Some(rect) = Self::parse_rect(&rng) else {
                return Err(format!("引用「{line}」的区域看不懂"));
            };
            list.push(sheetcore::consolidate::Source { sheet, rect });
        }
        if list.is_empty() {
            return Err("至少填一行引用位置，例如 一月!A1:B10".into());
        }
        let at = self.sel;
        let rep = sheetcore::consolidate::consolidate(
            &mut self.wb,
            self.sheet_idx,
            at,
            &list,
            f,
            row_labels,
            col_labels,
        )?;
        self.wb.dirty = true;
        self.doc_gen = self.doc_gen.wrapping_add(1);
        self.status = format!(
            "合并计算（{}）：{} 行 × {} 列，写在 {}",
            f.label(),
            rep.rows,
            rep.cols,
            cell_name(at.0, at.1)
        );
        Ok(self.status.clone())
    }

    /// 列字母或 1 起的列号
    fn parse_col(s: &str) -> Option<u32> {
        let t = s.trim().trim_end_matches("列");
        if t.is_empty() {
            return None;
        }
        if let Ok(n) = t.parse::<u32>() {
            return Some(n.saturating_sub(1));
        }
        let mut v = 0u32;
        for ch in t.chars() {
            if !ch.is_ascii_alphabetic() {
                return None;
            }
            v = v * 26 + (ch.to_ascii_uppercase() as u32 - 'A' as u32 + 1);
        }
        Some(v.saturating_sub(1))
    }

    /// 预测工作表对话框
    fn forecast_dialog(&mut self, ctx: &egui::Context) {
        let Some(mut d) = self.fc_dlg.clone() else { return };
        let mut open = true;
        let mut ok = false;
        ui_kit::window(ctx, "ETS 预测工作表", 450.0)
            .open(&mut open)
            .resizable(false)
            .show(ctx, |ui| {
                ui_kit::field(ui, "数据区域", |ui| {
                    ui.add(
                        egui::TextEdit::singleline(&mut d.range)
                            .desired_width(290.0)
                            .hint_text("A1:B13（时间列+数值列）或 A1:A13"),
                    );
                });
                ui_kit::field(ui, "预测期数", |ui| {
                    let mut v = d.periods as f64;
                    if ui_kit::spin(ui, &mut v, 1.0, 120.0, 1.0, 70.0) {
                        d.periods = v as u32;
                    }
                });
                ui_kit::field(ui, "季节周期", |ui| {
                    let mut sv = d.season_len as f64;
                    if ui_kit::spin(ui, &mut sv, 0.0, 52.0, 1.0, 70.0) {
                        d.season_len = sv as usize;
                    }
                    ui.label(egui::RichText::new("0 = 自动检测周期（如 4 季度 / 12 月）").size(10.5).weak());
                });
                ui_kit::field(ui, "置信区间", |ui| {
                    let mut cv = d.confidence as f64;
                    if ui_kit::spin(ui, &mut cv, 50.0, 99.0, 1.0, 70.0) {
                        d.confidence = cv as u8;
                    }
                    ui.label("%");
                });
                ui.label(
                    egui::RichText::new("采用 Holt-Winters 指数平滑（ETS）模型，自动估计水平/趋势/季节性并输出置信上下界与模型评估指标。")
                        .size(10.5)
                        .weak(),
                );
                if !d.msg.is_empty() {
                    ui.label(
                        egui::RichText::new(&d.msg)
                            .size(11.0)
                            .color(egui::Color32::from_rgb(192, 0, 0)),
                    );
                }
                ui_kit::footer(ui, |ui| {
                    if ui_kit::secondary_button(ui, "取消").clicked() {
                        open = false;
                    }
                    if ui_kit::primary_button(ui, "创建").clicked() {
                        ok = true;
                    }
                });
            });
        if ok {
            match self.forecast_run_opts(&d.range, d.periods.max(1), d.season_len, d.confidence) {
                Ok(_) => self.fc_dlg = None,
                Err(e) => {
                    d.msg = e;
                    self.fc_dlg = Some(d);
                }
            }
        } else {
            self.fc_dlg = if open { Some(d) } else { None };
        }
    }

    /// 分类汇总对话框
